window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[6]=[{"id":"06_19","g":6,"l":19,"topic":"Как работает реклама: практикум","module":"Маркетинг","format":"Проектная мастерская","skills":["Работа с клиентом","Командная работа","Критическое мышление"],"goal":"К концу урока ученик сможет разобрать рекламу по схеме «Кому? Что? Как?» (потребитель, предложение, приёмы, товарный знак и слоган) и оценить по 3 критериям, сработает ли она для своего потребителя.","criteria":["Я определяю в рекламе потребителя, предложение и приёмы.","Я оцениваю рекламу по 3 критериям: понятно ли, нужно ли этому потребителю, честно ли.","Я предлагаю одно улучшение и объясняю, почему оно поможет."],"result":"Командная «Карта разбора рекламы» для 2 реклам с оценкой «сработает / не сработает» и улучшенная версия одной рекламы (новый слоган или призыв).","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Реклама (advertising)","real":"Информация о товаре для многих людей, которая привлекает внимание и побуждает купить","shown":"Информация о товаре для многих людей, которая привлекает внимание и побуждает купить","truth":true,"first":"Р"},{"term":"Маркетинг (marketing)","real":"Работа компании, чтобы понять покупателя и продать ему нужный товар","shown":"Обращена ко многим, говорит о товаре, цель — интерес и покупка","truth":false,"first":"М"},{"term":"Потребитель рекламы","real":"Человек, которому адресована реклама","shown":"Человек, которому адресована реклама","truth":true,"first":"П"},{"term":"Товарный знак","real":"Рисунок, слово или символ, по которому узнают товар или компанию; его нельзя копировать","shown":"Работа компании, чтобы понять покупателя и продать ему нужный товар","truth":false,"first":"Т"},{"term":"Рекламный слоган","real":"Короткая запоминающаяся фраза о товаре","shown":"Короткая запоминающаяся фраза о товаре","truth":true,"first":"Р"},{"term":"Признаки рекламы","real":"Обращена ко многим, говорит о товаре, цель — интерес и покупка","shown":"Рисунок, слово или символ, по которому узнают товар или компанию; его нельзя копировать","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Информация о товаре для многих людей, которая привлекает внимание и побуждает купить"},{"term":"Маркетинг (marketing)","def":"Работа компании, чтобы понять покупателя и продать ему нужный товар"},{"term":"Потребитель рекламы","def":"Человек, которому адресована реклама"},{"term":"Товарный знак","def":"Рисунок, слово или символ, по которому узнают товар или компанию; его нельзя копировать"},{"term":"Рекламный слоган","def":"Короткая запоминающаяся фраза о товаре"},{"term":"Признаки рекламы","def":"Обращена ко многим, говорит о товаре, цель — интерес и покупка"},{"term":"Практика (practice)","def":"Выполнение задания на деле"}],"english":"advertising — реклама; marketing — маркетинг; practice — практика","concepts":{"head":"Понятия","items":["Реклама (advertising) — инструмент маркетинга (marketing).","Потребитель — тот, кому она адресована.","Товарный знак — символ, по которому узнают компанию: например, три полоски у Adidas или «галочка» Nike.","Слоган — короткая фраза.","Сегодня практика (practice): учимся разбирать рекламу как специалисты."]},"steps":{"head":"Как разобрать рекламу, по шагам","items":["КОМУ — кто потребитель (возраст, интересы); ЧТО — какой товар и чем он полезен; КАК — какие приёмы: картинка, цвет, слоган, товарный знак, отзыв, скидка, призыв; затем ОЦЕНКА по 3 критериям: понятно ли с первого взгляда, нужно ли это потребителю, честно ли (правдиво, конкретно)","Если хотя бы один критерий не выполнен, реклама, скорее всего, сработает хуже"]},"scheme":"Три колонки «Кому? Что? Как?», под ними «весы» оценки с тремя гирьками: понятно, нужно, честно.","examples":[{"lab":"Пример","text":"Плакат «Кружок робототехники для 5–7 классов, первое занятие бесплатно, далее 4 000 условных тенге в месяц, запись у вожатой»: кому — школьники 5–7 классов; что — кружок; как — бесплатное первое занятие и понятный призыв. Оценка: понятно, нужно, честно — сработает."},{"lab":"Казахстанский пример","text":"Реклама казахстанских молочных брендов на упаковке подчёркивает «местное молоко» и узнаваемый товарный знак, чтобы покупатель быстро нашёл продукт на полке."}],"mistake":{"myth":"Оценивают рекламу по «нравится — не нравится»","fix":"Спросить «Ты ли потребитель этой рекламы?» и оценивать с точки зрения того, кому она адресована."},"check":[{"q":"Зачем компании товарный знак?","a":"Чтобы её товар узнавали и не путали"},{"q":"Сработает ли реклама игрушек для взрослых бизнесменов?","a":"Нет, не тот потребитель"},{"q":"Что значит «конкретно»?","a":"Есть цена, факты, понятно, что предлагают"}],"kz":{"text":"Шоколад «Казахстан» фабрики «Рахат». Этот товар знают многие поколения казахстанцев, его упаковка и название стали узнаваемым знаком. Что? Как?».","link":"узнаваемая упаковка и название сами работают как реклама — покупатель сразу находит товар."},"world":{"text":"Товарные знаки защищены во всём мире: Всемирная организация интеллектуальной собственности (ВОИС) помогает компаниям разных стран регистрировать свои знаки. Подделки известных брендов вредят и компаниям, и покупателям.","link":""},"fact":"«Галочку» Nike в 1971 году нарисовала студентка Кэролин Дэвидсон, и за работу ей тогда заплатили всего 35 долларов. Позже компания подарила ей акции и золотое кольцо с этим знаком (сайт компании Nike, энциклопедия).","cards":[{"n":"1","title":"Узнай рекламу","lines":["Тренер показывает 4 товарных знака без названий. Запишите, какой компании они принадлежат и по какой детали вы их узнали."],"hand":null,"answers":[]},{"n":"2","title":"Карта разбора рекламы","lines":["Реклама А: «КРУЖОК РОБОТОТЕХНИКИ! Для 5–7 классов. Первое занятие бесплатно, дальше — 4 000 условных тенге в месяц. Собери своего первого робота! Запись у вожатой до 15-го числа».","Реклама Б: «Мега-ручка! Пишет вечно! Купи, не пожалеешь! Цена при встрече».","Задание: для каждой рекламы заполните «Кому? Что? Как?», оцените по критериям «понятно — нужно — честно», сделайте вывод «сработает / не сработает». Улучшите рекламу Б: напишите новый честный текст с ценой (например, 350 условных тенге) и призывом."],"hand":"Сдать: карту на листе А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Прошло три месяца. «Я разобрал(а) рекламу и не купил(а) лишнего, когда…» Закончи фразу и подчеркни одно действие на ближайшие 48 часов."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"«Думай о малом»","minutes":9,"source":"Реклама Volkswagen «Think Small», агентство DDB, США, 1959","hook":"В стране огромных машин рекламируют крошечного «жука». Провал?","story":["В конце 1950-х американцы любили большие блестящие автомобили. А Volkswagen привёз маленький, странный на вид «Жук».","Агентство DDB сделало необычную рекламу: огромное белое поле, крошечная машина в углу и заголовок «Think Small» — «Думай о малом».","В тексте честно и с юмором говорилось о маленькой машине: мало бензина, легко парковаться, дешёвый ремонт."],"question":"Почему, по-вашему, такая реклама сработала?","options":["Она честно превратила «недостаток» в преимущество и выделялась среди других","В ней снялась звезда","Она обещала скидку","Она была самой дорогой"],"answerIndex":0,"reveal":"«Think Small» стала одной из самых известных реклам XX века. Она не притворялась, что «Жук» большой, а превратила маленький размер в плюс. И среди ярких реклам выделялась простотой.","teams":"Команды: возьмите «недостаток» своего ярмарочного товара и превратите его в преимущество одной фразой.","takeaway":"Честность и непохожесть на других делают рекламу заметной."},{"type":"case","title":"Тот, кем мог бы пахнуть ваш мужчина","minutes":8,"source":"Реклама Old Spice «The Man Your Man Could Smell Like», агентство Wieden+Kennedy, 2010","hook":"Старый бренд дедушкиного одеколона. Как сделать его модным?","story":["Old Spice долго считался «одеколоном дедушки».","В 2010 году вышел ролик: актёр за 30 секунд без склеек переходит из ванной на яхту, а потом на коня, разговаривая прямо со зрителем.","После успеха ролика команда за пару дней записала около 180 коротких видео-ответов на комментарии людей в соцсетях."],"question":"Что, по-вашему, было главным в этой рекламе?","options":["Длинный список свойств геля","Низкая цена","Скрытая реклама","Юмор и разговор прямо со зрителем, а потом — ответы людям в соцсетях"],"answerIndex":3,"reveal":"Ролик стал вирусным, а видео-ответы людям сделали бренд «живым». Old Spice перестал быть дедушкиным. Реклама работает, когда с аудиторией говорят на её языке.","teams":"Команды: снимите (или разыграйте) 15-секундный ролик-обращение к покупателю вашего товара — с юмором и без склеек.","takeaway":"Хорошая реклама говорит с покупателем, а не о товаре."}],"homework":"Найди упаковку любого товара дома и разбери её как рекламу по схеме «Кому? Что? Как?». Найди товарный знак и слоган, оцени по 3 критериям.","support":"Карта разбора с вопросами-подсказками в каждой колонке и список приёмов рекламы для выбора.","advanced":"Придумать для одной рекламы версию для другого потребителя (например, для родителей вместо школьников) и объяснить, что изменится.","photo":{"src":"lessons/img/06_19.jpg","author":"Zoshua Colah","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему покупать подделки с чужим товарным знаком нечестно и может быть опасно?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l19.pptx","name":"19. Как работает реклама — практикум (6 кл).pptx","mb":1.5}},{"id":"06_20","g":6,"l":20,"topic":"Маркетинговый PR (Public Relations)","module":"Маркетинг","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление","Креативность"],"goal":"К концу урока ученик сможет отличить PR от рекламы по 3 признакам (кто говорит, цель, оплата места) и предложить честное PR-событие для школьного проекта с планом из 4 пунктов.","criteria":["Я называю 3 отличия PR от рекламы и привожу пример.","Я предлагаю PR-событие, которое укрепляет доверие к проекту и подходит школе.","Я пишу короткую честную новость-анонс о событии."],"result":"«PR-план школьного проекта»: идея PR-события, цель, кто о нём расскажет (школьная газета, родители, гости), ожидаемый результат и одна новость-анонс для школьного сайта или чата.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Маркетинг (marketing)","real":"Вся работа компании, чтобы понять покупателя и продать ему нужный товар","shown":"Вся работа компании, чтобы понять покупателя и продать ему нужный товар","truth":true,"first":"М"},{"term":"PR (Public Relations, связи с общественностью)","real":"Работа над тем, чтобы люди знали о компании, хорошо к ней относились и доверяли ей","shown":"Мнение людей о компании или человеке","truth":false,"first":"P"},{"term":"Реклама","real":"Платное сообщение о товаре, цель которого — продажа здесь и сейчас","shown":"Платное сообщение о товаре, цель которого — продажа здесь и сейчас","truth":true,"first":"Р"},{"term":"PR-менеджер","real":"Специалист, который отвечает за отношения компании с людьми и СМИ, готовит новости и события","shown":"Работа над тем, чтобы люди знали о компании, хорошо к ней относились и доверяли ей","truth":false,"first":"P"},{"term":"PR-ход (пиар-ход)","real":"Заметное событие или действие, о котором люди захотят рассказать сами","shown":"Заметное событие или действие, о котором люди захотят рассказать сами","truth":true,"first":"P"},{"term":"Репутация","real":"Мнение людей о компании или человеке","shown":"Специалист, который отвечает за отношения компании с людьми и СМИ, готовит новости и события","truth":false,"first":"Р"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Маркетинг (marketing)","def":"Вся работа компании, чтобы понять покупателя и продать ему нужный товар"},{"term":"PR (Public Relations, связи с общественностью)","def":"Работа над тем, чтобы люди знали о компании, хорошо к ней относились и доверяли ей"},{"term":"Реклама","def":"Платное сообщение о товаре, цель которого — продажа здесь и сейчас"},{"term":"PR-менеджер","def":"Специалист, который отвечает за отношения компании с людьми и СМИ, готовит новости и события"},{"term":"PR-ход (пиар-ход)","def":"Заметное событие или действие, о котором люди захотят рассказать сами"},{"term":"Репутация","def":"Мнение людей о компании или человеке"},{"term":"Менеджер","def":"Руководитель, который планирует и организует работу"}],"english":"marketing — маркетинг; PR — связи с общественностью","concepts":{"head":"Понятия","items":["Маркетинг (marketing) — общая стратегия: понять покупателя, создать товар, продать.","Реклама — часть маркетинга: платное сообщение «купи сейчас».","PR (связи с общественностью) — тоже часть маркетинга, но его цель — доверие и хорошая репутация.","PR-менеджер готовит события и новости.","PR-ход — событие, о котором люди рассказывают сами."]},"steps":{"head":"Отличия по шагам","items":["КТО ГОВОРИТ: в рекламе — сама компания, в PR — журналисты, гости, покупатели; ЦЕЛЬ: реклама — продажа сейчас, PR — доверие надолго; ОПЛАТА: в рекламе платят за место (щит, ролик), в PR — за подготовку события, а рассказывают о нём бесплатно, если оно интересно","Как сделать PR-событие: выбрать цель; придумать полезное и интересное событие; пригласить гостей и тех, кто расскажет; подготовить новость; после события поблагодарить участников"]},"scheme":"Две колонки «Реклама» и «PR» и три строки: «Кто говорит?», «Цель?», «Платим за?»; внизу цепочка PR-события: цель → событие → гости → новость → благодарность.","examples":[{"lab":"Пример","text":"Школьная кофейня проводит «День открытых кружек»: каждый может попробовать новый чай бесплатно, а часть выручки дня — например, 5 000 из 20 000 условных тенге — передаётся в приют для животных. Об этом пишет"},{"lab":"Школьная газета","text":"Это PR."},{"lab":"Казахстанский пример","text":"Казахстанские компании проводят благотворительные акции и субботники, например высаживают деревья в городах; о них рассказывают новости, и у людей растёт доверие к компании."}],"mistake":{"myth":"«PR — это обман и шумиха»","fix":"Объяснить, что честный PR рассказывает о реальных хороших делах; пиар на обмане быстро разрушает доверие."},"check":[{"q":"Плакат «Скидка на булочки» — реклама или PR?","a":"Реклама"},{"q":"Статья в газете о том, как школьная команда собрала книги для сельской библиотеки, — что это?","a":"PR"},{"q":"Почему PR должен быть честным?","a":"Если обман раскроется, репутация испортится"}],"kz":{"text":"Экологическая акция «Таза Қазақстан» («Чистый Казахстан»). В ней участвуют школы, жители и многие казахстанские компании: они выходят на субботники, сажают деревья и рассказывают об этом в новостях и соцсетях.","link":"когда компания вместе с людьми делает полезное дело, о ней рассказывают новости и у людей растёт доверие — это PR, а не реклама."},"world":{"text":"ЦУР ООН № 17 «Партнёрство ради целей» и ЦУР № 13 «Борьба с изменением климата»: многие компании мира поддерживают экологические и социальные проекты и открыто рассказывают о них. При этом важно не заниматься «гринвошингом» — не делать вид, что компания заботится о природе, если это не так.","link":""},"fact":"Одним из основателей профессии PR считают американца Айви Ли: в 1906 году он опубликовал «Декларацию принципов», где обещал давать журналистам точную и честную информацию о компаниях (энциклопедия, статья «Айви Ли»).","cards":[{"n":"2","title":"PR-план школьного проекта","lines":["Проект на выбор: школьная кофейня (чай по 150 условных тенге), мастерская закладок, клуб настольных игр.","Заполните: 1) цель PR (что люди должны думать о проекте); 2) PR-событие (полезное, интересное, без обмана); 3) кто о нём расскажет (школьная газета, сайт, родители, гости); 4) ожидаемый результат (например, 30 гостей и 10 отзывов); 5) новость-анонс до 50 слов: что, где, когда, зачем. Если часть выручки идёт на доброе дело, посчитайте: выручка 12 000 условных тенге, на доброе дело — 25%."],"hand":"Сдать: PR-план.","answers":[["","3 000 условных тенге."]]}],"practice":[{"type":"case","title":"Кризис «Тайленола»","minutes":10,"source":"Компания Johnson & Johnson, Чикаго, 1982","hook":"Кто-то подложил яд в таблетки известного бренда. Как спасти доверие?","story":["В 1982 году в Чикаго несколько человек погибли, приняв капсулы «Тайленол» — популярного лекарства от боли.","Оказалось, преступник подмешал яд в упаковки прямо на полках магазинов. Компания не была виновата.","Но покупатели боялись, а журналисты писали о «Тайленоле» каждый день."],"question":"Что, по-вашему, сделала компания?","options":["Промолчала и подождала, пока все забудут","Снизила цену в два раза","Отозвала таблетки по всей стране, открыто говорила с прессой и придумала защищённую упаковку","Обвинила магазины"],"answerIndex":2,"reveal":"Johnson & Johnson отозвала препарат по всей стране, хотя это стоило огромных денег, открыто общалась с журналистами и вернула «Тайленол» в упаковке с защитой от вскрытия. Доверие вернулось. Этот случай — классика PR в кризис.","teams":"Команды: на ярмарке покупатель пожаловался, что ваш товар сломался. Напишите короткое честное заявление команды из 3 предложений.","takeaway":"PR в кризис: быстро, честно и заботясь о людях."},{"type":"case","title":"Курица, которая закончилась","minutes":8,"source":"KFC в Великобритании, февраль 2018","hook":"Сеть ресторанов курицы осталась… без курицы. Как извиниться?","story":["В 2018 году KFC в Великобритании сменила компанию-доставщика, и в сотни ресторанов перестала приезжать курица.","Многие рестораны закрылись на несколько дней. Покупатели были злы, о проблеме писали все газеты.","KFC нужно было извиниться так, чтобы люди не отвернулись от бренда."],"question":"Как, по-вашему, лучше всего извиниться в такой ситуации?","options":["Закрыть все рестораны навсегда","Обвинить покупателей","Сделать вид, что ничего не случилось","С юмором и честно признать ошибку на весь газетный разворот"],"answerIndex":3,"reveal":"KFC напечатала в газетах рекламу с пустым ведром, где буквы KFC были переставлены в шуточное слово, и честно извинилась. Юмор + признание вины понравились людям, а рекламу потом наградили.","teams":"Команды: придумайте извинение «с юмором, но честно» для ситуации: на ярмарке закончился ваш главный товар.","takeaway":"Признать ошибку — лучший PR-ход, особенно с человеческим лицом."}],"homework":"Найди в новостях пример PR-события любой казахстанской компании или организации (акция, субботник, благотворительность). Запиши: что произошло, кто об этом рассказал, чем это отличается от рекламы.","support":"Таблица «Реклама или PR» с 6 примерами для сортировки и шаблон новости «Что? Где? Когда? Зачем? Кто приглашён?».","advanced":"Продумать, как измерить успех PR-события (сколько гостей пришло, сколько людей прочитало новость, сколько отзывов) и что делать, если на событии что-то пошло не так.","photo":{"src":"lessons/img/06_20.jpg","author":"Matt C","q":["Что вы видите на фото? Как это связано с нашей темой?","Как понять, что компания действительно делает доброе дело, а не только говорит о нём?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l20.pptx","name":"20. Маркетинговый PR (Public Relations) (6 кл).pptx","mb":1.4}},{"id":"06_21","g":6,"l":21,"topic":"Бренд","module":"Маркетинг","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление","Креативность"],"goal":"К концу урока ученик сможет назвать 5 элементов бренда (название, логотип, слоган, цвета, обещание покупателю) и разобрать по ним бренд одной казахстанской компании.","criteria":["Я называю 5 элементов бренда и объясняю, зачем нужен каждый.","Я разбираю бренд казахстанской компании по этим элементам.","Я объясняю разницу между брендом, брендингом и ребрендингом."],"result":"«Паспорт бренда» казахстанской компании: 5 элементов бренда, ассоциации покупателей и вывод, что обещает бренд; плюс набросок элементов бренда для школьного проекта.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Бренд (brand)","real":"Образ товара или компании в голове покупателя: что он вспоминает, чувствует и чего ждёт, услышав название","shown":"Образ товара или компании в голове покупателя: что он вспоминает, чувствует и чего ждёт, услышав название","truth":true,"first":"Б"},{"term":"Маркетинг (marketing)","real":"Работа компании, чтобы понять покупателя и продать ему нужный товар","shown":"Обновление бренда: новый логотип, цвета или слоган, когда компания меняется","truth":false,"first":"М"},{"term":"Логотип","real":"Рисунок или особое написание названия, по которому узнают компанию","shown":"Рисунок или особое написание названия, по которому узнают компанию","truth":true,"first":"Л"},{"term":"Рекламный слоган","real":"Короткая запоминающаяся фраза о товаре или компании","shown":"Работа компании, чтобы понять покупателя и продать ему нужный товар","truth":false,"first":"Р"},{"term":"Брендинг","real":"Работа по созданию и развитию бренда: название, логотип, цвета, стиль общения","shown":"Работа по созданию и развитию бренда: название, логотип, цвета, стиль общения","truth":true,"first":"Б"},{"term":"Ребрендинг","real":"Обновление бренда: новый логотип, цвета или слоган, когда компания меняется","shown":"Короткая запоминающаяся фраза о товаре или компании","truth":false,"first":"Р"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бренд (brand)","def":"Образ товара или компании в голове покупателя: что он вспоминает, чувствует и чего ждёт, услышав название"},{"term":"Маркетинг (marketing)","def":"Работа компании, чтобы понять покупателя и продать ему нужный товар"},{"term":"Логотип","def":"Рисунок или особое написание названия, по которому узнают компанию"},{"term":"Рекламный слоган","def":"Короткая запоминающаяся фраза о товаре или компании"},{"term":"Брендинг","def":"Работа по созданию и развитию бренда: название, логотип, цвета, стиль общения"},{"term":"Ребрендинг","def":"Обновление бренда: новый логотип, цвета или слоган, когда компания меняется"},{"term":"Обещание бренда","def":"То главное, что покупатель получает, выбирая этот бренд"}],"english":"brand — бренд; marketing — маркетинг","concepts":{"head":"Понятия","items":["Бренд (brand) — не просто название, а то, что покупатель думает и чувствует о товаре.","Брендинг — часть маркетинга (marketing): работа по созданию бренда.","Ребрендинг — его обновление.","Логотип и слоган — видимые части бренда."]},"steps":{"head":"Как устроен бренд, по шагам","items":["Название — короткое, легко произносится","Логотип — простой знак, который узнают даже маленьким","Цвета — одни и те же везде: на упаковке, сайте, вывеске","Слоган — коротко говорит, чем вы особенные","Обещание — главное, что получает покупатель (вкус, удобство, надёжность)","Если все элементы работают вместе и компания выполняет обещание, у покупателя появляется доверие и привычка выбирать бренд"]},"scheme":"«звезда бренда» — в центре «Обещание», 4 луча: название, логотип, цвета, слоган; рядом стрелка «Брендинг → Бренд → Ребрендинг (обновление)».","examples":[{"lab":"Школьный проект «Тёплая кружка»","text":"Название — «Тёплая кружка», логотип — кружка с паром, цвета — оранжевый и коричневый, слоган «Перемена с теплом», обещание — горячий чай за 2 минуты, стакан — 150 условных тенге."},{"lab":"Казахстанский пример","text":"Air Astana — название связано со столицей, логотип с орнаментом и узнаваемые фирменные цвета, обещание — надёжные и комфортные перелёты; бренд узнают в аэропортах разных стран."}],"mistake":{"myth":"«Бренд — это дорогая вещь»","fix":"У любого товара, даже недорогого, может быть сильный бренд, если его узнают и ему доверяют; бренд — про узнаваемость и доверие, а не про цену."},"check":[{"q":"Чем бренд отличается от логотипа?","a":"Логотип — знак, бренд — весь образ в голове покупателя"},{"q":"Зачем компании ребрендинг?","a":"Чтобы обновиться, когда компания или покупатели изменились"},{"q":"Что будет, если бренд не выполняет обещание?","a":"Покупатели перестанут доверять"}],"kz":{"text":"Air Astana — национальная авиакомпания Казахстана. У неё узнаваемый логотип с казахским орнаментом, фирменные цвета и форма экипажа, а обещание — надёжные и комфортные полёты.","link":"все элементы бренда работают вместе и показывают Казахстан в мире."},"world":{"text":"Бренды многих мировых компаний узнают в любой стране по логотипу и цветам. Но бренд может и потерять доверие, если компания нарушает обещания или вредит природе — ЦУР ООН № 12 «Ответственное потребление и производство» напоминает о честности производителей.","link":""},"fact":"Слово «бренд» происходит от древнескандинавского слова brandr — «гореть, клеймо»: раньше скотоводы ставили на животных клеймо, чтобы отличить своих. У казахов похожую роль выполняла тамга — родовой знак, которым отмечали скот и имущество (энциклопедия, статьи «Бренд» и «Тамга»).","cards":[{"n":"2","title":"Паспорт бренда","lines":["Часть 1. Выберите казахстанский бренд (например: Air Astana, Kaspi.kz, «Рахат», «Казахтелеком» или другой, который знаете). Заполните: название и что оно значит; логотип (нарисуйте); фирменные цвета; слоган, если знаете; обещание покупателю; 3 слова-ассоциации у вашей команды.","Часть 2. Ваш школьный проект продаёт напитки по 150 условных тенге. Придумайте название, нарисуйте логотип, выберите 2 цвета, слоган до 5 слов и обещание."],"hand":"Сдать: паспорт на листе А3.","answers":[]}],"practice":[{"type":"case","title":"«Новая кола»","minutes":10,"source":"Компания Coca-Cola, запуск New Coke, апрель — июль 1985","hook":"Новый вкус победил в слепых тестах. Почему покупатели возмутились?","story":["В 1980-х Pepsi проводила «вызов Pepsi»: люди с закрытыми глазами пробовали две колы и часто выбирали Pepsi.","Coca-Cola изменила рецепт на более сладкий. В слепых тестах новый вкус нравился людям больше.","В апреле 1985 года старую колу убрали из продажи и выпустили «Новую колу»."],"question":"Что, по-вашему, произошло дальше?","options":["Новая кола стала самой популярной","Люди протестовали, и через 79 дней старую колу вернули","Coca-Cola перестала продавать колу","Никто не заметил разницы"],"answerIndex":1,"reveal":"Тысячи людей звонили и писали жалобы: у них «отняли» любимый напиток. Уже через 79 дней старая кола вернулась под названием «Coca-Cola Classic». Компания поняла: бренд — это не только вкус, а память и чувства людей.","teams":"Команды: что в вашем ярмарочном товаре нельзя менять, потому что это «душа бренда»? А что можно улучшать?","takeaway":"Бренд — это чувства покупателей, а не только свойства товара."},{"type":"case","title":"Логотип за 35 долларов","minutes":8,"source":"Логотип Nike «Swoosh», студентка Кэролин Дэвидсон, 1971","hook":"Один из самых известных логотипов в мире нарисовала студентка. Сколько ей заплатили?","story":["В 1971 году Фил Найт, основатель будущей Nike, попросил студентку-дизайнера Кэролин Дэвидсон нарисовать логотип для кроссовок.","Она нарисовала «галочку» — символ движения и крыла богини победы Ники.","Найту логотип сначала не очень понравился, но времени было мало, и его утвердили."],"question":"Сколько, по-вашему, заплатили за логотип?","options":["1 миллион долларов","35 долларов","Ничего","10 000 долларов"],"answerIndex":1,"reveal":"Кэролин Дэвидсон получила 35 долларов. Позже Nike подарила ей золотое кольцо с «галочкой» и акции компании. Логотип сам по себе ничего не стоил — ценность ему придали годы работы бренда.","teams":"Команды: нарисуйте простой знак для бренда своего товара — такой, чтобы его можно было нарисовать за 5 секунд.","takeaway":"Сильный логотип простой, а ценность ему даёт бренд."}],"homework":"Найди дома 3 товара казахстанских производителей. Для одного составь паспорт бренда: название, логотип, цвета, слоган (если есть) и что обещает бренд.","support":"Шаблон «звезды бренда» с вопросами-подсказками и готовые изображения логотипов казахстанских компаний для разбора.","advanced":"Предложить ребрендинг для одного школьного проекта или кружка: что изменить и почему, сохранив узнаваемость.","photo":{"src":"lessons/img/06_21.jpg","author":"Vagaro","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой мировой бренд вы узнаёте без названия и что он вам обещает?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l21.pptx","name":"21. Бренд (6 кл).pptx","mb":1.4}},{"id":"06_22","g":6,"l":22,"topic":"Как построить личный бренд","module":"Маркетинг","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление","Инициативность"],"goal":"К концу урока ученик сможет описать, каким он хочет быть в глазах других (3 качества и одно дело, которым он полезен), и составить 3 конкретных шага к этому на ближайший месяц.","criteria":["Я называю 3 качества, которыми хочу, чтобы меня знали, и подтверждаю их примерами.","Я придумываю личный слоган и знак, которые отражают эти качества.","Я составляю 3 конкретных шага с сроками и понимаю, как безопасно рассказывать о себе."],"result":"Личная «Карта бренда»: 3 качества, «моё полезное дело», личный слоган до 5 слов, личный знак-логотип и 3 шага на месяц.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Бренд (brand)","real":"Образ товара, компании или человека в голове других людей","shown":"Образ товара, компании или человека в голове других людей","truth":true,"first":"Б"},{"term":"Личный бренд","real":"То, каким тебя знают и помнят другие: твои качества, дела и репутация","shown":"Обновление образа, когда человек или компания меняются","truth":false,"first":"Л"},{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять людей и предложить им нужное","shown":"Работа, чтобы понять людей и предложить им нужное","truth":true,"first":"М"},{"term":"Рекламный слоган","real":"Короткая запоминающаяся фраза; у личного бренда — фраза о тебе","shown":"То, каким тебя знают и помнят другие: твои качества, дела и репутация","truth":false,"first":"Р"},{"term":"Логотип","real":"Знак, по которому узнают; у человека это может быть личный символ","shown":"Знак, по которому узнают; у человека это может быть личный символ","truth":true,"first":"Л"},{"term":"Ребрендинг","real":"Обновление образа, когда человек или компания меняются","shown":"Короткая запоминающаяся фраза; у личного бренда — фраза о тебе","truth":false,"first":"Р"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Бренд (brand)","def":"Образ товара, компании или человека в голове других людей"},{"term":"Личный бренд","def":"То, каким тебя знают и помнят другие: твои качества, дела и репутация"},{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять людей и предложить им нужное"},{"term":"Рекламный слоган","def":"Короткая запоминающаяся фраза; у личного бренда — фраза о тебе"},{"term":"Логотип","def":"Знак, по которому узнают; у человека это может быть личный символ"},{"term":"Ребрендинг","def":"Обновление образа, когда человек или компания меняются"},{"term":"Репутация","def":"Мнение людей о тебе, которое складывается из твоих поступков"}],"english":"brand — бренд; marketing — маркетинг","concepts":{"head":"Понятия","items":["Бренд (brand) бывает не только у компаний, но и у людей.","Личный бренд — то, что о тебе думают и рассказывают другие.","Он складывается из дел, а не из слов.","Как в маркетинге (marketing): сначала понять, чем ты полезен людям, потом честно об этом рассказывать."]},"steps":{"head":"Как построить личный бренд, по шагам","items":["Узнай себя — что тебе нравится и что получается (рисуешь, объясняешь, чинишь, организуешь); выбери 3 качества, которыми хочешь, чтобы тебя знали (например, надёжный, творческий, добрый); найди «полезное дело» — чем ты можешь помогать другим; делай это регулярно; рассказывай честно и безопасно — через школьные проекты, выставки, конкурсы; помни: личные данные (адрес, телефон, школу) в интернете не публикуем; проверяй, совпадает ли то, что ты говоришь, с тем, что делаешь"]},"scheme":"«дом личного бренда» — фундамент «Мои дела», стены «3 качества», крыша «Слоган и знак», дверь «Безопасность в интернете».","examples":[{"lab":"Пример","text":"Ученица Аружан хорошо рисует и хочет, чтобы её знали как творческую и отзывчивую. Её шаги: нарисовать афишу для школьной ярмарки к пятнице; провести для младших мастер-класс по закладкам (закладки затем продали по 300 условных тенге, выручка от 15 штук — 4 500 условных тенге пошла в фонд класса); оформить своё портфолио рисунков к концу месяца."},{"lab":"Казахстанский пример","text":"Певец Димаш Кудайберген известен как талантливый и трудолюбивый исполнитель, который бережно относится к казахской культуре; его личный бренд построен на годах занятий и выступлений."}],"mistake":{"myth":"«Личный бренд — это много подписчиков»","fix":"Спросить, кому вы больше доверяете — человеку с подписчиками или однокласснику, который всегда держит слово; бренд — это доверие."},"check":[{"q":"Из чего складывается личный бренд?","a":"Из поступков и дел"},{"q":"Можно ли построить личный бренд только словами?","a":"Нет, люди верят делам"},{"q":"Что нельзя публиковать о себе в интернете?","a":"Адрес, телефон, пароли, личные фото без разрешения родителей"}],"kz":{"text":"Димаш Кудайберген — казахстанский певец, известный во многих странах. Его образ связан с трудолюбием, уважением к казахской культуре и к слушателям, и он годами подтверждает его выступлениями.","link":"личный бренд строится на деле и честности."},"world":{"text":"ЦУР ООН № 4 «Качественное образование» и № 8 «Достойная работа»: во многих странах школьники собирают портфолио своих работ и достижений, чтобы показать свои умения. При этом во всём мире учат цифровой безопасности — не публиковать личные данные.","link":""},"fact":"Фразу «Ваш бренд — это то, что о вас говорят, когда вас нет в комнате» часто приписывают основателю Amazon Джеффу Безосу; она хорошо показывает, что бренд — это мнение других людей (книги и статьи о Джеффе Безосе).","cards":[{"n":"2","title":"Карта моего бренда","lines":["1) Что мне нравится и что получается: ___.","2) Три качества, которыми я хочу, чтобы меня знали, и пример поступка для каждого: ___.","3) Моё полезное дело для других: ___.","4) Личный слоган до 5 слов: ___.","5) Мой знак (нарисуй): ___.","6) Три шага на месяц со сроками: ___.","7) Правило безопасности: что я не публикую о себе в интернете: ___.","Чек-лист партнёра: качества подтверждены поступками? Шаги конкретные и со сроками?"],"hand":"Сдать: карту.","answers":[]}],"practice":[{"type":"case","title":"Чёрная водолазка","minutes":9,"source":"Стив Джобс и его образ: чёрная водолазка Issey Miyake, джинсы и кроссовки","hook":"Почему основатель Apple годами носил одно и то же?","story":["Стив Джобс почти на всех выступлениях появлялся в одном образе: чёрная водолазка, синие джинсы, серые кроссовки.","Водолазки ему делал японский дизайнер Иссей Мияке — по рассказам, целую стопку.","Джобс объяснял, что хотел носить «униформу», чтобы не тратить время на выбор и чтобы его узнавали."],"question":"Что, по-вашему, такой образ давал личному бренду Джобса?","options":["Ничего — это случайность","Он не любил моду","Узнаваемость и образ простоты, как у продуктов Apple","Экономию денег на одежде"],"answerIndex":2,"reveal":"Образ стал частью личного бренда: простой, узнаваемый, такой же минималистичный, как продукты Apple. Личный бренд складывается из того, что человек повторяет постоянно.","teams":"Команды: придумайте 3 «постоянных» детали личного бренда для ученика, который хочет стать известным блогером о шахматах.","takeaway":"Личный бренд — это то, что ты повторяешь и чем тебя узнают."},{"type":"case","title":"Профиль, который увидел работодатель","minutes":8,"source":"Условная ситуация","hook":"Подросток ищет подработку. Работодатель открывает его соцсети. Что он увидит?","story":["Арман хочет летом подрабатывать в детском лагере помощником вожатого.","Перед собеседованием руководитель лагеря смотрит его профиль в соцсетях.","В профиле: грубые комментарии двухлетней давности, но и видео, где Арман учит младших играть в футбол."],"question":"Что лучше всего сделать Арману до собеседования?","options":["Удалить вообще все соцсети","Ничего — никто не смотрит","Сделать профиль закрытым и соврать","Убрать грубые старые посты и показать полезное: видео с детьми"],"answerIndex":3,"reveal":"Работодатели и вузы действительно смотрят соцсети. Личный бренд можно улучшить: убрать то, за что стыдно, и показать, что ты умеешь и любишь. Честно, без вранья.","teams":"Команды: составьте чек-лист «5 правил профиля школьника», который не стыдно показать работодателю.","takeaway":"Интернет помнит всё: личный бренд строят каждый день."}],"homework":"Выполни первый шаг из своей карты бренда и запиши, что получилось. Спроси двух близких людей, какими тремя словами они описали бы тебя, и сравни с выбранными качествами.","support":"Список из 20 качеств и 10 «полезных дел» для выбора; шаблон шагов «Что сделаю — к какому сроку».","advanced":"Придумать, как рассказать о своём «полезном деле» в школе без интернета (стенгазета, выставка, мастер-класс), и спланировать это событие.","photo":{"src":"lessons/img/06_22.jpg","author":"Vagaro","q":["Что вы видите на фото? Как это связано с нашей темой?","Как рассказать о своих умениях, не нарушая свою безопасность в интернете?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l22.pptx","name":"22. Как построить личный бренд (6 кл).pptx","mb":1.3}},{"id":"06_23","g":6,"l":23,"topic":"Рекламные агентства","module":"Маркетинг","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление","Креативность"],"goal":"К концу урока ученик сможет описать по 6 шагам, как рекламное агентство готовит рекламную кампанию (бриф, исследование, идея, макет, размещение, оценка результата), и применить эти шаги к заказу школьного клиента.","criteria":["Я называю 6 шагов подготовки рекламной кампании по порядку.","Я заполняю бриф: кто клиент, что продаём, кому, какой бюджет.","Я предлагаю идею со слоганом и каналы, которые укладываются в бюджет."],"result":"«Мини-кампания агентства»: заполненный бриф школьного клиента, идея кампании со слоганом, выбранные каналы с бюджетом в условных тенге и способ проверить результат.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Реклама (advertising)","real":"Платное сообщение о товаре для многих людей","shown":"Платное сообщение о товаре для многих людей","truth":true,"first":"Р"},{"term":"Маркетинг (marketing)","real":"Работа компании, чтобы понять покупателя и продать ему нужный товар","shown":"Несколько рекламных сообщений, объединённых одной идеей и целью, на определённое время","truth":false,"first":"М"},{"term":"Рекламное агентство","real":"Компания, которая по заказу других компаний придумывает и запускает рекламу","shown":"Компания, которая по заказу других компаний придумывает и запускает рекламу","truth":true,"first":"Р"},{"term":"Рекламный агент","real":"Сотрудник агентства, который работает с клиентом и помогает продать ему услуги рекламы","shown":"Работа компании, чтобы понять покупателя и продать ему нужный товар","truth":false,"first":"Р"},{"term":"Бриф","real":"Короткое задание от клиента: что рекламируем, для кого, зачем, какой бюджет и срок","shown":"Короткое задание от клиента: что рекламируем, для кого, зачем, какой бюджет и срок","truth":true,"first":"Б"},{"term":"Рекламная кампания","real":"Несколько рекламных сообщений, объединённых одной идеей и целью, на определённое время","shown":"Сотрудник агентства, который работает с клиентом и помогает продать ему услуги рекламы","truth":false,"first":"Р"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Платное сообщение о товаре для многих людей"},{"term":"Маркетинг (marketing)","def":"Работа компании, чтобы понять покупателя и продать ему нужный товар"},{"term":"Рекламное агентство","def":"Компания, которая по заказу других компаний придумывает и запускает рекламу"},{"term":"Рекламный агент","def":"Сотрудник агентства, который работает с клиентом и помогает продать ему услуги рекламы"},{"term":"Бриф","def":"Короткое задание от клиента: что рекламируем, для кого, зачем, какой бюджет и срок"},{"term":"Рекламная кампания","def":"Несколько рекламных сообщений, объединённых одной идеей и целью, на определённое время"},{"term":"Рекламный слоган","def":"Короткая запоминающаяся фраза о товаре"}],"english":"advertising — реклама; marketing — маркетинг","concepts":{"head":"Понятия","items":["Рекламное агентство — команда творческих людей, которые делают рекламу (advertising) для других компаний.","Это часть рынка маркетинга (marketing).","Рекламный агент общается с клиентом.","Бриф — задание клиента.","Рекламная кампания — серия реклам с общей идеей."]},"steps":{"head":"Как агентство готовит кампанию, по шагам","items":["1 — бриф: клиент рассказывает, что продаёт, кому, зачем, какой бюджет и срок; 2 — исследование: агентство изучает покупателей и конкурентов; 3 — идея: мозговой штурм, выбор главной мысли и слогана; 4 — макет: рисуют плакаты, пишут тексты, снимают ролики; клиент утверждает; 5 — размещение: выбирают каналы (интернет, наружная реклама, ТВ) и запускают; 6 — оценка: считают, сколько людей увидели рекламу и выросли ли продажи","В агентстве работают разные специалисты: агент (менеджер по клиентам), копирайтер (тексты), дизайнер, медиапланер (каналы)"]},"scheme":"Конвейер из 6 шагов-шестерёнок «Бриф → Исследование → Идея → Макет → Размещение → Оценка», над ним роли: агент, копирайтер, дизайнер, медиапланер.","examples":[{"lab":"Пример","text":"Школьная кофейня заказывает кампанию «Тёплая перемена» с бюджетом 3 000 условных тенге: 2 плаката по 500, 40 листовок по 25 (1 000), пост в школьном чате бесплатно, остаток 1 000 — на дегустацию. Оценка: продажи выросли с 30 до 45 стаканов в день."},{"lab":"Казахстанский пример","text":"Казахстанские рекламные агентства готовят кампании для банков, мобильных операторов и городских праздников, например к Наурызу, на казахском и русском языках."}],"mistake":{"myth":"Ученики сразу рисуют плакат, пропуская бриф и исследование","fix":"Спросить «Для кого этот плакат и какой у нас бюджет?» — без брифа ответить нельзя."},"check":[{"q":"С чего начинается работа агентства?","a":"С брифа"},{"q":"Зачем исследование?","a":"Понять покупателя и не повторить конкурента"},{"q":"Как узнать, сработала ли кампания?","a":"Посчитать охват и изменение продаж"}],"kz":{"text":"Социальная реклама к праздникам и акциям в Казахстане, например к Наурызу и акции «Таза Қазақстан». Такие кампании готовят рекламные агентства по заказу городских акиматов и компаний, на казахском и русском языках, с плакатами на улицах и роликами в интернете.","link":"каждая кампания проходит путь от брифа до оценки."},"world":{"text":"Крупные рекламные агентства работают сразу во многих странах и адаптируют одну кампанию под разные языки и культуры. При этом всё больше агентств поддерживают социальную рекламу, например о ЦУР ООН — о чистой воде, образовании, защите природы.","link":""},"fact":"Одно из первых рекламных агентств в мире открыл в 1840-х годах в Филадельфии (США) Волни Палмер: он покупал места в газетах и перепродавал их компаниям для рекламы (энциклопедия, статья «Рекламное агентство»).","cards":[{"n":"2","title":"Бриф клиента","lines":["Клиент: клуб настольных игр в школе. Что рекламируем: открытые игровые вечера по пятницам, вход 300 условных тенге. Для кого: ученики 5–8 классов.","Цель: чтобы на вечер приходило не 10, а 25 человек. Бюджет: 4 000 условных тенге. Срок кампании: 2 недели.","Прайс-лист каналов: плакат А3 — 500; листовка — 25 за штуку; объявление по школьному радио — 1 000; пост в школьном чате — бесплатно (с разрешения администрации); стенд у столовой — 1 500.","Задание агентства: 1) задайте клиенту 2 уточняющих вопроса; 2) придумайте идею и слоган кампании; 3) выберите каналы и посчитайте бюджет, не больше 4 000; 4) напишите, как проверите результат. Посчитайте, какая будет выручка клуба за вечер, если придут 25 человек."],"hand":"Сдать: мини-кампанию на листе А3.","answers":[["","7 500 условных тенге."]]}],"practice":[{"type":"case","title":"«Просто сделай это»","minutes":9,"source":"Слоган Nike «Just Do It», агентство Wieden+Kennedy, 1988","hook":"Как три слова стали девизом для миллионов людей?","story":["В 1988 году агентство Wieden+Kennedy готовило для Nike новую рекламную кампанию.","Основатель агентства Дэн Видэн придумал слоган «Just Do It» — «Просто сделай это».","В первом ролике 80-летний бегун Уолт Стэк рассказывал, как бегает 17 миль каждое утро."],"question":"Почему, по-вашему, Nike доверила рекламу агентству, а не сделала её сама?","options":["Агентство профессионально придумывает идеи и смотрит на бренд со стороны","Nike не умела делать кроссовки","Так требует закон","Агентство было бесплатным"],"answerIndex":0,"reveal":"Рекламные агентства — это команды креативщиков, стратегов, дизайнеров и медиапланеров. Они смотрят на бренд со стороны и находят идею, которая говорит с людьми. «Just Do It» стал одним из самых известных слоганов в истории.","teams":"Команды: станьте агентством для соседней команды — придумайте им слоган из 3–4 слов.","takeaway":"Агентство видит бренд со стороны и превращает его в идею."},{"type":"case","title":"«Думай иначе»","minutes":8,"source":"Кампания Apple «Think Different», агентство TBWA\\Chiat\\Day, 1997","hook":"Компания почти обанкротилась. Как напомнить людям, кто она?","story":["В 1997 году Apple была в тяжёлом положении. В компанию вернулся Стив Джобс.","Агентство TBWA\\Chiat\\Day предложило кампанию «Think Different»: в ней не было компьютеров.","Показывали фотографии людей, изменивших мир: Эйнштейна, Ганди, Пикассо — «тех, кто думает иначе»."],"question":"Почему в рекламе компьютеров не показали ни одного компьютера?","options":["Компьютеров ещё не было","Рекламировали не товар, а ценности бренда: смелость и творчество","Забыли","Компьютеры были некрасивыми"],"answerIndex":1,"reveal":"Кампания напомнила людям, за что любить Apple: за творчество и смелость. Это реклама ценностей, а не характеристик. Вскоре вышел яркий компьютер iMac, и компания начала подниматься.","teams":"Команды: сделайте рекламу своего товара без самого товара — покажите только ценность, которую он даёт.","takeaway":"Сильная реклама продаёт ценности, а не характеристики."}],"homework":"Найди рекламу любого казахстанского события или товара и попробуй восстановить её бриф: что рекламируют, для кого, зачем, какие каналы использованы. Запиши, как можно проверить, сработала ли кампания.","support":"Шаблон брифа с вопросами и прайс-лист каналов с готовыми ценами; памятка с 6 шагами.","advanced":"Рассчитать два варианта размещения в рамках бюджета и обосновать, какой даст больший охват; придумать способ измерить результат.","photo":{"src":"lessons/img/06_23.jpg","author":"Tim van der Kuip","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую социальную рекламную кампанию вы бы сделали для своего города?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l23.pptx","name":"23. Рекламные агентства (6 кл).pptx","mb":1.4}},{"id":"06_24","g":6,"l":24,"topic":"Маркетинговый проект: продвигаем товар","module":"Маркетинг","format":"Проектная мастерская","skills":["Работа с клиентом","Принятие решений","Командная работа"],"goal":"К концу урока ученик сможет назвать 6 шагов плана продвижения товара (товар и его польза, покупатель, цель, сообщение, каналы и бюджет, проверка результата) и вместе с командой составить черновик такого плана для товара школьного стартапа.","criteria":["Я называю 6 шагов плана продвижения по порядку.","Я вместе с командой заполняю каждый шаг для нашего товара конкретно, с цифрами.","Я объясняю, почему выбранные каналы подходят нашему покупателю и укладываются в бюджет."],"result":"Черновик «Плана продвижения товара» команды на одном листе: товар и польза, портрет покупателя, цель в цифрах, сообщение и слоган, каналы с бюджетом в условных тенге, способ проверки.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Товар (product)","real":"То, что продают покупателю, чтобы решить его задачу или порадовать","shown":"То, что продают покупателю, чтобы решить его задачу или порадовать","truth":true,"first":"Т"},{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя, сделать нужный товар и продать его","shown":"Общий план, как достичь цели","truth":false,"first":"М"},{"term":"Проект (project)","real":"Дело с целью, сроками, командой и результатом","shown":"Дело с целью, сроками, командой и результатом","truth":true,"first":"П"},{"term":"Стартап","real":"Новая небольшая компания или проект на самом первом этапе","shown":"Работа, чтобы понять покупателя, сделать нужный товар и продать его","truth":false,"first":"С"},{"term":"Продвижение","real":"Все действия, чтобы покупатели узнали о товаре и захотели его купить: реклама, PR, акции","shown":"Все действия, чтобы покупатели узнали о товаре и захотели его купить: реклама, PR, акции","truth":true,"first":"П"},{"term":"Стратегия","real":"Общий план, как достичь цели","shown":"Новая небольшая компания или проект на самом первом этапе","truth":false,"first":"С"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Товар (product)","def":"То, что продают покупателю, чтобы решить его задачу или порадовать"},{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя, сделать нужный товар и продать его"},{"term":"Проект (project)","def":"Дело с целью, сроками, командой и результатом"},{"term":"Стартап","def":"Новая небольшая компания или проект на самом первом этапе"},{"term":"Продвижение","def":"Все действия, чтобы покупатели узнали о товаре и захотели его купить: реклама, PR, акции"},{"term":"Стратегия","def":"Общий план, как достичь цели"},{"term":"Коммуникация","def":"Общение с покупателями: что, как и где мы им говорим"}],"english":"product — товар; marketing — маркетинг; project — проект","concepts":{"head":"Понятия","items":["Стартап — новый проект (project) на первых этапах.","Товар (product) — то, что продаём.","Продвижение — часть маркетинга (marketing): как покупатель узнаёт о товаре.","Стратегия — общий план.","Коммуникация — наше общение с покупателем."]},"scheme":"Лестница из 6 ступеней с подписями шагов, наверху флаг «Продажи», сбоку стрелка «Проверка → улучшение плана».","examples":[{"lab":"Пример","text":"Стартап «Эко-закладки» из переработанной бумаги, цена 250 условных тенге. Покупатель — ученики 5–7 классов, которые любят читать. Цель — 40 штук. Сообщение: «Читай с заботой о природе». Каналы: плакат у библиотеки (500), 20 листовок по 25 (500), мини-выставка на перемене (бесплатно). Бюджет 1 000. Плановая выручка 40 × 250 = 10 000."},{"lab":"Казахстанский пример","text":"Казахстанские производители продуктов, выводя новый товар в магазины, проводят дегустации в супермаркетах и одновременно запускают рекламу в соцсетях — используют несколько каналов."}],"mistake":{"myth":"Команда выбирает каналы, не подумав о покупателе (например, реклама в газете для пятиклассников)","fix":"Вернуться к шагу 2 и спросить: «Где бывает наш покупатель?»."},"check":[{"q":"С какого шага начинается план?","a":"С товара и его пользы"},{"q":"Почему цель нужна в цифрах?","a":"Чтобы потом проверить, достигли ли"},{"q":"Как узнать, какой канал сработал?","a":"Спросить покупателей, откуда узнали, и посчитать"}],"kz":{"text":"Казахстанские молочные и кондитерские бренды, например «Рахат». Выводя новый вкус, такие компании используют несколько каналов: упаковку, рекламу в соцсетях, дегустации в магазинах.","link":"у каждого продвижения есть план — товар, покупатель, сообщение, каналы и проверка."},"world":{"text":"ЦУР ООН № 12 «Ответственное потребление и производство»: во многих странах стартапы продвигают экологичные товары и честно рассказывают, из чего они сделаны. Покупатели всё чаще выбирают товары, которые не вредят природе.","link":""},"fact":"Продавцы давно знают силу бесплатной пробы: ещё на старинных базарах Востока торговцы давали покупателю попробовать фрукты, сладости и специи. Сегодня дегустации в супермаркетах по всему миру используют ту же идею (энциклопедия, статья «Дегустация»).","cards":[{"n":"2","title":"План продвижения товара","lines":["Товар на выбор: эко-закладки (250 условных тенге), брелоки из фетра (400), домашнее печенье (200 за пакет).","Прайс-лист каналов: плакат А3 — 500; листовка — 25 за штуку; объявление по школьному радио — 1 000; дегустация или мини-выставка — бесплатно; пост в школьном чате — бесплатно (с разрешения администрации). Бюджет — не больше 1 500 условных тенге.","Заполните 6 шагов: 1) товар и польза; 2) покупатель; 3) цель в цифрах; 4) сообщение и слоган; 5) каналы и бюджет; 6) как проверим результат. Посчитайте плановую выручку и сколько штук нужно продать, чтобы покрыть бюджет продвижения."],"hand":"Сдать: план на листе А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Прошло три месяца. «Наш товар узнали и купили, потому что…» Закончи фразу и подчеркни одно действие на ближайшие 48 часов."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"Место за друга","minutes":9,"source":"Реферальная программа Dropbox, 2008–2010","hook":"Как облачное хранилище выросло без больших затрат на рекламу?","story":["Dropbox — сервис для хранения файлов в интернете. Сначала компания пробовала платную рекламу, но она стоила слишком дорого.","Тогда сделали так: пригласи друга — и вы оба получите бесплатное дополнительное место.","Люди стали приглашать друзей сотнями тысяч."],"question":"Почему, по-вашему, такая программа сработала лучше рекламы?","options":["Выгоду получали оба, а другу доверяют больше, чем рекламе","Место было платным","Друзья были обязаны","Реклама была запрещена"],"answerIndex":0,"reveal":"Реферальная программа дала Dropbox огромный рост: пользователей стало во много раз больше. Секрет — выгода для обоих и доверие к рекомендации друга.","teams":"Команды: придумайте «пригласи друга» для ярмарки: что получит покупатель и его друг?","takeaway":"Рекомендация друга — самый сильный канал продвижения."},{"type":"case","title":"Камень в коробке","minutes":8,"source":"Pet Rock («Камень-питомец»), Гэри Даль, США, 1975","hook":"Можно ли продать обычный камень? А миллион камней?","story":["В 1975 году американец Гэри Даль пошутил с друзьями о «идеальном питомце», которого не надо кормить и выгуливать.","Он стал продавать обычные гладкие камни в картонной коробке с дырочками для «дыхания» и смешной инструкцией по уходу.","Камень-питомец стал хитом к Рождеству."],"question":"Что, по-вашему, на самом деле покупали люди?","options":["Очень полезную вещь","Камень для строительства","Шутку, историю и забавный подарок","Ценный минерал"],"answerIndex":2,"reveal":"Камень-питомец продали больше миллиона раз за несколько месяцев. Люди покупали не камень, а юмор и историю — упаковку, инструкцию и повод посмеяться. Мода быстро прошла, но Даль заработал.","teams":"Команды: придумайте «историю» и упаковку для самого обычного предмета из пенала, чтобы его захотели купить в подарок.","takeaway":"Продвижение продаёт историю и эмоцию."}],"homework":"Опроси 3 возможных покупателей вашего товара (одноклассников или членов семьи): нужен ли им такой товар, сколько они готовы заплатить и где им удобнее узнать о нём. Принеси ответы для доработки плана.","support":"Шаблон плана с вопросами-подсказками на каждом шаге и примером заполненного плана «Эко-закладки».","advanced":"Добавить в план запасной канал на случай, если основной не сработает, и посчитать, сколько штук нужно продать, чтобы окупить бюджет продвижения.","photo":{"src":"lessons/img/06_24.jpg","author":"Kaleidico","q":["Что вы видите на фото? Как это связано с нашей темой?","Как рассказать о пользе экологичного товара так, чтобы это было честно и интересно?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l24.pptx","name":"24. Маркетинговый проект — продвигаем товар (6 кл).pptx","mb":1.3}},{"id":"06_25","g":6,"l":25,"topic":"Ярмарка: продвижение товара","module":"Маркетинг","format":"Симуляция, ярмарка","skills":["Работа с клиентом","Финансовое мышление","Командная работа"],"goal":"К концу урока ученик сможет выполнить свою роль в продвижении товара на ярмарке (зазывала, автор плаката, ведущий дегустации, учётчик каналов) и посчитать выручку, затраты на продвижение и прибыль команды, отметив, откуда пришёл каждый покупатель.","criteria":["Я выполняю свою роль в продвижении товара по плану команды.","Я записываю каждую продажу и канал, из которого пришёл покупатель.","Я правильно считаю выручку, затраты на продвижение и прибыль."],"result":"Работающая точка продаж команды с продвижением по плану (плакат, слоган, акция или дегустация) и «Лист учёта продаж и каналов»: кто купил, сколько, откуда узнал.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Место, где продавцы и покупатели встречаются для торговли","shown":"Место, где продавцы и покупатели встречаются для торговли","truth":true,"first":"Я"},{"term":"Товар (product)","real":"То, что продают покупателю","shown":"Все деньги от продаж: цена × количество","truth":false,"first":"Т"},{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя и продать ему нужный товар","shown":"Работа, чтобы понять покупателя и продать ему нужный товар","truth":true,"first":"М"},{"term":"Канал продвижения","real":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, сарафанное радио","shown":"То, что продают покупателю","truth":false,"first":"К"},{"term":"Затраты на продвижение","real":"Деньги, потраченные на рекламу и акции","shown":"Деньги, потраченные на рекламу и акции","truth":true,"first":"З"},{"term":"Выручка","real":"Все деньги от продаж: цена × количество","shown":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, сарафанное радио","truth":false,"first":"В"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Место, где продавцы и покупатели встречаются для торговли"},{"term":"Товар (product)","def":"То, что продают покупателю"},{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя и продать ему нужный товар"},{"term":"Канал продвижения","def":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, сарафанное радио"},{"term":"Затраты на продвижение","def":"Деньги, потраченные на рекламу и акции"},{"term":"Выручка","def":"Все деньги от продаж: цена × количество"},{"term":"Прибыль","def":"Выручка минус все затраты"}],"english":"fair — ярмарка; product — товар; marketing — маркетинг","concepts":{"head":"Понятия","items":["На ярмарке (fair) мы проверяем план продвижения товара (product) на деле.","Канал продвижения — как покупатель узнал о товаре.","Маркетинг (marketing) работает, если продвижение приводит покупателей."]},"steps":{"head":"Как работает команда на ярмарке, по шагам","items":["Подготовить точку — ценники, плакат, образцы; распределить роли: продавец, кассир, зазывала, ведущий дегустации или акции, учётчик каналов; при каждой продаже учётчик спрашивает «Откуда вы о нас узнали?» и ставит отметку; реагировать на события рынка, не обманывая покупателя; после торговли посчитать: выручка = цена × количество; прибыль = выручка − затраты на товар − затраты на продвижение"]},"scheme":"В центре «Наша точка», к ней 4 стрелки-канала (зазывала, плакат, дегустация, друзья) со счётчиками; внизу формула прибыли.","examples":[{"lab":"Пример","text":"Команда продаёт печенье по 200 условных тенге: затраты на продукты — 1 500, на продвижение (плакат и листовки) — 1 000. Продали 25 пакетов: выручка 5 000, прибыль 5 000 − 1 500 − 1 000 = 2 500. По листу учёта: 12 покупателей привёл зазывала, 8 — дегустация, 5 — плакат."},{"lab":"Казахстанский пример","text":"На ярмарках выходного дня в городах Казахстана продавцы угощают покупателей кусочком сыра или яблока — бесплатная проба часто приводит больше покупателей, чем вывеска."}],"mistake":{"myth":"Забывают вычесть затраты на продвижение и считают прибыль больше, чем она есть","fix":"На доске посчитать два варианта и показать разницу."},"check":[{"q":"Выручка 6 000, затраты на товар 2 000, на продвижение 1 500 — прибыль?","a":"2 500"},{"q":"Зачем спрашивать покупателя, откуда он узнал?","a":"Чтобы понять, какой канал работает"},{"q":"Можно ли обещать покупателю то, чего нет, чтобы продать?","a":"Нет, это обман и вредит репутации"}],"kz":{"text":"Ярмарки выходного дня в Алматы, Астане и других городах Казахстана. Фермеры и небольшие производители продвигают свои товары прямо на месте: угощают пробой, громко зовут покупателей, ставят яркие вывески.","link":"продвижение на ярмарке — живой маркетинг с разными каналами."},"world":{"text":"ЦУР ООН № 8 «Достойная работа и экономический рост»: во многих странах мира малый бизнес начинается с рынков и ярмарок, где продавцы учатся привлекать покупателей и честно торговать.","link":""},"fact":"Выражение «сарафанное радио» означает рекламу из уст в уста: когда покупатели сами рассказывают друзьям о товаре. Многие маркетологи считают рекомендацию знакомого одним из самых убедительных каналов, потому что ей доверяют больше, чем рекламе (энциклопедия, статья «Сарафанное радио»).","cards":[{"n":"2","title":"Наша точка продаж","lines":["Роли: продавец, кассир, зазывала, ведущий дегустации или акции, учётчик каналов.","Данные для расчёта: затраты на товар — 1 500 условных тенге, на продвижение — 1 000, цена — 200 за штуку.","Лист учёта: № покупателя | сколько купил | сумма | откуда узнал (зазывала / плакат / дегустация / друзья).","Итог: выручка = ___; прибыль = выручка − 1 500 − 1 000 = ___."],"hand":"Сдать: лист учёта.","answers":[]},{"n":"3","title":"События рынка","lines":["Событие 1. «Покупатель спрашивает, полезное ли печенье». Ответьте честно, не преувеличивая.","Событие 2. «У соседней команды закончился товар, их покупатели ищут, где купить». Как вы поможете и привлечёте покупателей честно?","Событие 3. «Ваш плакат упал и порвался». Что сделаете за 1 минуту?"],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"«А это смешается?»","minutes":9,"source":"Видео-серия Blendtec «Will It Blend?», США, с 2006 года","hook":"Как продавать блендеры, если о них никто не говорит?","story":["Компания Blendtec делала мощные блендеры, но о них мало кто знал.","Директор Том Диксон в белом халате стал снимать видео: он бросал в блендер разные предметы — шарики, грабли, даже смартфоны — и спрашивал: «Will it blend?» («А это смешается?»).","Видео стали популярными на YouTube."],"question":"Что, по-вашему, показывали эти ролики покупателю?","options":["Цену блендера","Мощность блендера — наглядно и весело","Как сломать телефон","Рецепты коктейлей"],"answerIndex":1,"reveal":"Ролики собрали миллионы просмотров, и продажи блендеров выросли. Демонстрация «вживую» убеждает лучше слов. А юмор заставляет делиться видео.","teams":"Команды: придумайте 20-секундную демонстрацию своего товара на ярмарке — покажите, а не рассказывайте.","takeaway":"Лучшее продвижение — показать товар в деле."},{"type":"case","title":"Ледяной вызов","minutes":8,"source":"Ice Bucket Challenge, сбор средств для фонда ALS Association, лето 2014","hook":"Обливание ледяной водой собрало огромные деньги на лечение болезни. Как?","story":["Летом 2014 года люди по всему миру обливали себя ведром ледяной воды, снимали это на видео и передавали вызов трём друзьям.","Участники жертвовали деньги на исследование болезни БАС (ALS).","К челленджу присоединились знаменитости, спортсмены и политики."],"question":"Что, по-вашему, сделало этот челлендж таким популярным?","options":["Простое правило, весело, и каждый передаёт вызов друзьям","Он был обязательным","За участие платили","Большая рекламная кампания по ТВ"],"answerIndex":0,"reveal":"Фонд ALS Association собрал за несколько недель больше 100 миллионов долларов. Механика простая: сделай, сними, передай трём друзьям. Так продвижение распространяется само.","teams":"Команды: придумайте челлендж для продвижения ярмарки в школе — простой, весёлый и с передачей друзьям.","takeaway":"Механика «передай другу» распространяет идею сама."}],"homework":"Сохрани лист учёта команды. Посчитай, сколько покупателей привёл каждый канал, и сколько условных тенге продвижения пришлось на одного покупателя (затраты на продвижение : число покупателей).","support":"Готовый лист учёта со значками каналов (только поставить отметку) и памятка с формулами.","advanced":"Посчитать, какой канал принёс больше выручки на каждый потраченный тенге, и предложить, как перераспределить бюджет продвижения.","photo":{"src":"lessons/img/06_25.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие способы привлечь покупателя работают на ярмарке в любой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l25.pptx","name":"25. Ярмарка — продвижение товара (6 кл).pptx","mb":1.6}},{"id":"06_26","g":6,"l":26,"topic":"Маркетинговый проект: продвигаем товар: практикум","module":"Маркетинг","format":"Проектная мастерская","skills":["Лидерство","Работа с клиентом","Командная работа"],"goal":"К концу урока команда сможет составить план продвижения товара для ярмарки по модели 5P (товар, цена, место, продвижение, люди), где каждый пункт заполнен конкретно и с цифрами в условных тенге.","criteria":["Я объясняю, что означает каждая буква модели 5P.","Я вместе с командой заполняю все 5 пунктов для нашего товара конкретно и с цифрами.","Я отвечаю за один пункт плана и могу защитить его перед классом."],"result":"Командный «План 5P» товара для ярмарки на листе А3: описание товара, цена с расчётом прибыли, место и оформление точки, каналы продвижения с бюджетом, роли людей и сервис для покупателя.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Товар (product)","real":"То, что продаём, и чем он полезен покупателю","shown":"То, что продаём, и чем он полезен покупателю","truth":true,"first":"Т"},{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя и продать ему нужный товар","shown":"Новый проект на первых этапах","truth":false,"first":"М"},{"term":"Проект (project)","real":"Дело с целью, сроком, командой и результатом","shown":"Дело с целью, сроком, командой и результатом","truth":true,"first":"П"},{"term":"Модель 5P","real":"План маркетинга из 5 частей, названия которых по-английски начинаются на «P»: товар (product), цена (price), место (place), продвижение (promotion), люди (people)","shown":"Работа, чтобы понять покупателя и продать ему нужный товар","truth":false,"first":"М"},{"term":"Услуга","real":"Работа, которую делают для покупателя, например упаковка подарка или мастер-класс","shown":"Работа, которую делают для покупателя, например упаковка подарка или мастер-класс","truth":true,"first":"У"},{"term":"Стартап","real":"Новый проект на первых этапах","shown":"План маркетинга из 5 частей, названия которых по-английски начинаются на «P»: товар (product), цена (price), место (place), продвижение (promotion), люди (people)","truth":false,"first":"С"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Товар (product)","def":"То, что продаём, и чем он полезен покупателю"},{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя и продать ему нужный товар"},{"term":"Проект (project)","def":"Дело с целью, сроком, командой и результатом"},{"term":"Модель 5P","def":"План маркетинга из 5 частей, названия которых по-английски начинаются на «P»: товар (product), цена (price), место (place), продвижение (promotion), люди (people)"},{"term":"Услуга","def":"Работа, которую делают для покупателя, например упаковка подарка или мастер-класс"},{"term":"Стартап","def":"Новый проект на первых этапах"},{"term":"Практика (practice)","def":"Выполнение задания на деле"}],"english":"product — товар; marketing — маркетинг; project — проект","concepts":{"head":"Понятия","items":["Модель 5P помогает не забыть ничего важного в маркетинге (marketing).","Product — товар (product) или услуга: что продаём и чем полезно.","Price — цена: сколько стоит и выгодно ли нам и покупателю.","Place — место: где и как продаём, как выглядит точка.","Promotion — продвижение: как покупатель узнает (реклама, PR, акции).","People — люди: кто продаёт, как общается, какой сервис."]},"steps":{"head":"Как составить план 5P, по шагам","items":["Описать товар и пользу; посчитать затраты на 1 штуку и выбрать цену выше затрат, но приятную покупателю; выбрать место и оформление точки; выбрать 2–3 канала продвижения в рамках бюджета; распределить роли и придумать правило вежливого сервиса; проверить, что все 5 пунктов согласованы между собой"]},"scheme":"Рука с 5 пальцами, на каждом — одна «P» и вопрос: что? сколько? где? как узнают? кто и как обслуживает?","examples":[{"lab":"Пример","text":"Стартап «Тёплые варежки для кружки» (вязаные чехлы): товар — чехол, который сохраняет чай тёплым; цена — затраты 300, цена 600 условных тенге, прибыль 300 со штуки; место — стол у входа в столовую, украшенный пряжей; продвижение — плакат (500) и демонстрация «чай остаётся тёплым» (бесплатно); люди — продавец показывает, как надеть чехол, и говорит «спасибо»."},{"lab":"Казахстанский пример","text":"Сеть кофеен в казахстанских городах выбирает место у университетов (place), делает фирменные стаканы (product), проводит акции для студентов (promotion) и обучает бариста дружелюбному сервису (people)."}],"mistake":{"myth":"Пункты не согласованы — дорогой товар продают с неряшливой точки, или продвижение говорит о скидке, которой нет","fix":"Прочитать план вслух от начала до конца и спросить: «Верит ли покупатель всему сразу?»."},"check":[{"q":"Что относится к Place?","a":"Где и как продаём, оформление точки"},{"q":"Почему цена должна быть выше затрат?","a":"Иначе не будет прибыли"},{"q":"Зачем пятое P — люди?","a":"Покупатель запоминает, как с ним говорили"}],"kz":{"text":"Kaspi.kz как пример всех 5P. Товар — удобное приложение с покупками и платежами; цена — понятные условия; место — телефон покупателя и пункты выдачи по всему Казахстану; продвижение — реклама и акции; люди — служба поддержки.","link":"сильная компания продумывает все 5P."},"world":{"text":"Модель маркетинга на буквы «P» используют компании по всему миру: от маленьких кафе до международных корпораций. ЦУР ООН № 8 «Достойная работа и экономический рост» поддерживает развитие малого бизнеса, которому такой простой план помогает не забыть важное.","link":""},"fact":"Модель маркетинга «4P» (товар, цена, место, продвижение) предложил американский профессор Джером Маккарти в 1960 году. Позже к ней стали добавлять пятое P — люди (people), потому что для покупателя важен и сервис (энциклопедия, статья «Комплекс маркетинга»).","cards":[{"n":"2","title":"План 5P для ярмарки","lines":["Товар на выбор: вязаный чехол для кружки (затраты 300 условных тенге за штуку), набор из 3 открыток (затраты 150), домашнее печенье (затраты 80 за пакет). Бюджет на продвижение — до 1 500.","Заполните: Product — что продаём, польза, можно ли добавить услугу (упаковка, подпись). Price — цена, прибыль со штуки, сколько штук продадим и какая будет прибыль. Place — где стоит точка и как оформлена. Promotion — 2–3 канала, их стоимость. People — роли и правило сервиса (например, «улыбаемся, отвечаем честно, благодарим»). Проверьте: все пункты согласованы?"],"hand":"Сдать: план на листе А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Прошло три месяца. «Наш план 5P сработал, потому что…» Закончи фразу и подчеркни одно действие на ближайшие 48 часов."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"Воппер за один цент","minutes":9,"source":"Burger King, кампания «Whopper Detour», США, декабрь 2018","hook":"Как заставить людей скачать приложение? Отправить их… к конкуренту.","story":["Burger King хотел, чтобы больше людей скачали его приложение для заказов.","Придумали так: если ты подъедешь к ресторану McDonald's ближе чем на 600 футов (около 180 метров) и закажешь Воппер в приложении — он будет стоить 1 цент.","После заказа приложение отправляло человека в ближайший Burger King."],"question":"Почему, по-вашему, кампания стала такой обсуждаемой?","options":["McDonald's сам её придумал","Бургер стал бесплатным навсегда","Она была смелой и смешной: использовала конкурента как рекламу","Её никто не заметил"],"answerIndex":2,"reveal":"Приложение Burger King поднялось на первые места в магазинах приложений, о кампании писали все. Смелая и остроумная идея дала больше, чем дорогая обычная реклама.","teams":"Команды: придумайте смелую, но честную и не обидную акцию для своего товара, о которой захотят рассказать.","takeaway":"Смелая идея с юмором — бесплатная реклама."},{"type":"case","title":"«Наша пицца была плохой»","minutes":8,"source":"Domino's Pizza, кампания «Pizza Turnaround», США, 2009–2010","hook":"Покупатели говорят: ваша пицца — как картон. Что делать?","story":["Domino's получала много отзывов, что её пицца невкусная.","Компания поменяла рецепт теста, соуса и сыра.","А потом запустила рекламу, где показывала реальные плохие отзывы и признавала: да, наша пицца была плохой, мы её переделали."],"question":"Почему, по-вашему, признание ошибки помогло продажам?","options":["Конкуренты закрылись","Никто не смотрел рекламу","Честность вызвала доверие, а люди захотели попробовать новую пиццу","Пиццу стали отдавать бесплатно"],"answerIndex":2,"reveal":"Продажи Domino's выросли, а кампанию изучают как пример честного маркетинга. Продвижение сработало, потому что за ним стояло настоящее улучшение товара.","teams":"Команды: соберите 3 «отзыва» покупателей о вашем ярмарочном товаре и придумайте, как честно рассказать об улучшении.","takeaway":"Продвижение работает, если за ним стоит настоящее улучшение."}],"homework":"Доработай свою «P» в плане команды: добавь одну деталь, которая сделает её сильнее (например, точную цену с расчётом, эскиз оформления точки или фразу продавца).","support":"Шаблон 5P с вопросами-подсказками и примером заполненного плана; калькулятор для расчёта прибыли.","advanced":"Посчитать, сколько штук нужно продать, чтобы покрыть затраты на продвижение, и предложить услугу к товару, которая повысит его ценность.","photo":{"src":"lessons/img/06_26.jpg","author":"Kaleidico","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое из 5P важнее всего для маленького школьного стартапа и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l26.pptx","name":"26. Маркетинговый проект — продвигаем товар — практикум (6 кл).pptx","mb":1.3}},{"id":"06_27","g":6,"l":27,"topic":"Маркетинговый проект: этапы и защита","module":"Маркетинг","format":"Питч и защита","skills":["Работа с клиентом","Презентация","Командная работа"],"goal":"К концу урока ученик сможет назвать 5 этапов маркетингового проекта (идея и товар, исследование покупателя, план 5P, продвижение, оценка результата) и 4 критерия защиты, а также провести 2-минутный питч рекламной кампании своего стартапа по этим критериям.","criteria":["Я называю 5 этапов маркетингового проекта и 4 критерия защиты.","Я выступаю со своей частью питча уверенно, укладываюсь во время и показываю цифры.","Я оцениваю питчи других команд по критериям и даю обратную связь «плюс — что улучшить»."],"result":"2-минутный питч команды «Рекламная кампания нашего стартапа» по структуре из 5 этапов и лист оценки питчей других команд по 4 критериям защиты.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Питчи","min":20},{"stage":"Голосование","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя и продать ему нужный товар","shown":"Работа, чтобы понять покупателя и продать ему нужный товар","truth":true,"first":"М"},{"term":"Проект (project)","real":"Дело с целью, сроком, командой и результатом","shown":"Короткое (2–3 минуты) убедительное выступление, где команда представляет проект слушателям или инвесторам","truth":false,"first":"П"},{"term":"Стартап","real":"Новый проект на первых этапах","shown":"Новый проект на первых этапах","truth":true,"first":"С"},{"term":"Услуга","real":"Работа, которую делают для покупателя","shown":"Дело с целью, сроком, командой и результатом","truth":false,"first":"У"},{"term":"Модель 5P","real":"План из 5 частей: товар, цена, место, продвижение, люди","shown":"План из 5 частей: товар, цена, место, продвижение, люди","truth":true,"first":"М"},{"term":"Питч","real":"Короткое (2–3 минуты) убедительное выступление, где команда представляет проект слушателям или инвесторам","shown":"Работа, которую делают для покупателя","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя и продать ему нужный товар"},{"term":"Проект (project)","def":"Дело с целью, сроком, командой и результатом"},{"term":"Стартап","def":"Новый проект на первых этапах"},{"term":"Услуга","def":"Работа, которую делают для покупателя"},{"term":"Модель 5P","def":"План из 5 частей: товар, цена, место, продвижение, люди"},{"term":"Питч","def":"Короткое (2–3 минуты) убедительное выступление, где команда представляет проект слушателям или инвесторам"},{"term":"Критерии защиты","def":"Правила, по которым оценивают выступление"}],"english":"marketing — маркетинг; project — проект","concepts":{"head":"Понятия","items":["Маркетинговый проект (project) — путь от идеи до проверенного результата продаж.","Питч — короткая защита проекта.","Критерии защиты — по ним слушатели решают, убедил ли их проект."]},"scheme":"Дорога из 5 этапов проекта, под ней «часы питча» на 2 минуты с 7 секторами структуры, рядом 4 значка критериев.","examples":[{"lab":"Пример","text":"Питч стартапа «Эко-закладки»: «Сколько бумаги выбрасывает наш класс за неделю? Мы делаем закладки из переработанной бумаги по 250 условных тенге. Цель — 40 штук, бюджет продвижения 1 000, ожидаемая прибыль 6 000. Поддержите нас!»"},{"lab":"Казахстанский пример","text":"В Astana Hub стартапы защищают проекты перед экспертами за несколько минут и показывают цифры и пользу для клиента."}],"mistake":{"myth":"Команда читает текст с листа и не укладывается во время","fix":"Репетиция с таймером и правило «один говорит — остальные держат слайды и готовят ответы на вопросы»."},"check":[{"q":"Какой этап идёт после исследования?","a":"План 5P"},{"q":"Зачем в питче цифры?","a":"Они показывают, что проект реальный"},{"q":"Что такое «крючок»?","a":"Первая фраза, которая привлекает внимание"}],"kz":{"text":"Astana Hub — международный технопарк IT-стартапов в Астане. Молодые казахстанские команды защищают там свои проекты перед экспертами и инвесторами, показывая пользу для клиента и цифры.","link":"защита маркетингового проекта — это тот же питч, только в школе."},"world":{"text":"Во многих странах проводятся конкурсы школьных стартапов, где подростки представляют свои проекты в коротких питчах. Часто они посвящены ЦУР ООН — например, экологии или помощи людям.","link":""},"fact":"Выражение «питч в лифте» (elevator pitch) означает рассказ о проекте за время короткой поездки в лифте — примерно 30–60 секунд. Считается, что за это время нужно успеть заинтересовать важного собеседника (энциклопедия, статья «Elevator pitch»).","cards":[{"n":"1","title":"А теперь вопрос","lines":["По хлопку все меняются местами (своё и соседнее занимать нельзя). Последний севший отвечает 20 секунд. Вопросы раундов: «Какой навык делает тебя полезным команде?», «Что в нашем стартапе ты можешь объяснить лучше всех?»."],"hand":null,"answers":[]},{"n":"2","title":"Структура питча (2 минуты)","lines":["1) Крючок — вопрос или факт (10 сек). 2) Проблема покупателя (15 сек). 3) Наш товар или услуга (15 сек). 4) План 5P коротко (25 сек). 5) Рекламная кампания: слоган, каналы, бюджет (25 сек). 6) Цифры: цель продаж, ожидаемая выручка и прибыль в условных тенге (20 сек). 7) Призыв (10 сек). Распределите части между участниками."],"hand":null,"answers":[]},{"n":"3","title":"Лист оценки «инвестора»","lines":["Команда ___. Критерии (по 1–10): понятность ___; польза для покупателя ___; реальные цифры ___; уверенная подача и ответы ___. Плюс: ___. Что улучшить: ___. Сколько условных тенге из 10 000 вкладываю и почему: ___."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"Хлопья для президентов","minutes":9,"source":"Airbnb, «Obama O's» и «Cap'n McCain's», 2008","hook":"Стартапу не хватает денег. Основатели продают… хлопья.","story":["В 2008 году основатели Airbnb — сервиса для аренды жилья у людей — сидели без денег.","Шли выборы президента США. Они купили хлопья и сделали коробки «Obama O's» и «Cap'n McCain's» — с шутками про кандидатов.","Коробки продавали как коллекционные по 40 долларов."],"question":"Что, по-вашему, эта история показала инвесторам?","options":["Что основатели упорные и находчивые — они не сдаются","Что им нужен новый офис","Что выборы важнее бизнеса","Что Airbnb — компания хлопьев"],"answerIndex":0,"reveal":"Хлопья принесли основателям десятки тысяч долларов, и помогли продержаться. Позже известный инвестор Пол Грэм взял их в свою программу, впечатлившись именно этой упорностью. На защите проекта важны не только идея, но и команда.","teams":"Команды: подготовьте 1-минутную защиту проекта по шагам: проблема — решение — что уже сделали — что нужно.","takeaway":"На защите продают не только идею, но и команду."},{"type":"case","title":"Отказ в телешоу","minutes":8,"source":"Дверной звонок Ring, Джейми Симинофф, шоу «Shark Tank», 2013","hook":"Изобретателю отказали все инвесторы в телешоу. Конец?","story":["В 2013 году Джейми Симинофф пришёл в телешоу для предпринимателей «Shark Tank» с видеозвонком для двери — тогда он назывался DoorBot.","Он защищал проект перед инвесторами, но сделки не получилось.","Симинофф продолжил работать, улучшил продукт и переименовал его в Ring."],"question":"Что, по-вашему, произошло с компанией потом?","options":["Изобретатель бросил идею","Её купила Amazon в 2018 году","Её запретили","Она закрылась на следующий день"],"answerIndex":1,"reveal":"После шоу о звонке узнали миллионы зрителей, продажи выросли. В 2018 году Ring купила Amazon. Неудачная защита — не конец, а обратная связь.","teams":"Команды: составьте 3 трудных вопроса, которые может задать жюри, и подготовьте ответы на них.","takeaway":"Неудачная защита — это обратная связь, а не приговор."}],"homework":"Улучши свою часть питча по обратной связи: перепиши её так, чтобы уложиться в 30 секунд и добавить одну цифру. Потренируйся рассказать её дома вслух с таймером.","support":"Шаблон питча с началами фраз для каждого сектора («Знаете ли вы, что…», «Наш товар помогает…», «Наша цель — продать…») и роль в выступлении с короткой частью.","advanced":"Подготовить ответы на 3 самых трудных вопроса инвесторов и рассчитать, через сколько продаж окупится бюджет рекламной кампании.","photo":{"src":"lessons/img/06_27.jpg","author":"Kaleidico","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую проблему из ЦУР ООН мог бы решать ваш стартап и как сказать об этом в одной фразе?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l27.pptx","name":"27. Маркетинговый проект — этапы и защита (6 кл).pptx","mb":1.3}},{"id":"06_28","g":6,"l":28,"topic":"После ярмарки: какой канал продвижения сработал","module":"Маркетинг","format":"Симуляция, ярмарка","skills":["Работа с клиентом","Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет по листу учёта ярмарки определить, какой канал продвижения сработал лучше (по числу покупателей, выручке и затратам на одного покупателя), и проверить вывод во втором мини-раунде ярмарки.","criteria":["Я считаю по каждому каналу число покупателей, выручку и затраты на одного покупателя.","Я делаю вывод с опорой на цифры и наблюдения, а не на «мне кажется».","Я проверяю вывод во втором раунде и сравниваю результаты."],"result":"«Отчёт о каналах продвижения»: таблица каналов с числом покупателей, выручкой и затратами на одного покупателя за два раунда и вывод, какой канал оставить, усилить или убрать.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Место, где продавцы и покупатели встречаются для торговли","shown":"Место, где продавцы и покупатели встречаются для торговли","truth":true,"first":"Я"},{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя и продать ему нужный товар","shown":"Выручка минус все затраты","truth":false,"first":"М"},{"term":"Канал продвижения","real":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, друзья","shown":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, друзья","truth":true,"first":"К"},{"term":"Затраты на одного покупателя","real":"Сколько денег на продвижение потрачено, чтобы привлечь одного покупателя: затраты канала : число покупателей","shown":"Работа, чтобы понять покупателя и продать ему нужный товар","truth":false,"first":"З"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Все деньги от продаж","truth":true,"first":"В"},{"term":"Прибыль","real":"Выручка минус все затраты","shown":"Сколько денег на продвижение потрачено, чтобы привлечь одного покупателя: затраты канала : число покупателей","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ярмарка (fair)","def":"Место, где продавцы и покупатели встречаются для торговли"},{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя и продать ему нужный товар"},{"term":"Канал продвижения","def":"Способ, которым покупатель узнаёт о товаре: плакат, зазывала, дегустация, друзья"},{"term":"Затраты на одного покупателя","def":"Сколько денег на продвижение потрачено, чтобы привлечь одного покупателя: затраты канала : число покупателей"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Прибыль","def":"Выручка минус все затраты"}],"english":"fair — ярмарка; marketing — маркетинг","concepts":{"head":"Понятия","items":["В маркетинге (marketing) важно не только запустить рекламу, но и узнать, какой канал продвижения сработал.","Для этого на ярмарке (fair) мы спрашивали покупателей «Откуда вы о нас узнали?».","Затраты на одного покупателя показывают, насколько выгоден канал."]},"steps":{"head":"Как разобрать каналы, по шагам","items":["Взять лист учёта; посчитать для каждого канала число покупателей и выручку; записать затраты на канал; разделить затраты на число покупателей; сравнить: какой канал привёл больше покупателей и какой — дешевле на одного покупателя; добавить наблюдения (где стояли, что говорили); сделать вывод: оставить, усилить или убрать канал; проверить вывод во втором раунде"]},"scheme":"Таблица «Канал | Затраты | Покупатели | Выручка | Затраты на одного» и рядом три таблички-решения: «Оставить», «Усилить», «Убрать».","examples":[{"lab":"Пример","text":"Команда продавала печенье по 200 условных тенге. Плакат стоил 500 — привёл 5 покупателей (затраты на одного 100). Листовки стоили 500 — привели 2 покупателей (250 на одного). Зазывала и дегустация бесплатно — привели 12 и 8 покупателей. Вывод: убрать листовки, усилить дегустацию."},{"lab":"Казахстанский пример","text":"Казахстанские интернет-магазины и банки в приложениях смотрят, сколько покупателей пришло из каждого рекламного канала, и переносят бюджет туда, где покупатель обходится дешевле."}],"mistake":{"myth":"Команда выбирает «лучший» канал по симпатии («плакат красивый») или по одному покупателю","fix":"Вернуться к таблице и спросить, что говорят цифры."},"check":[{"q":"Канал стоил 600 и привёл 3 покупателей — затраты на одного?","a":"200"},{"q":"Канал бесплатный, но привёл 1 покупателя — хороший?","a":"Затрат нет, но и пользы мало; нужно смотреть и на число покупателей"},{"q":"Почему нужен второй раунд?","a":"Чтобы проверить вывод на деле"}],"kz":{"text":"Kaspi.kz. Продавцы, которые торгуют через Kaspi Магазин, видят в личном кабинете статистику продаж своих товаров и по этим цифрам решают, где и как продвигаться.","link":"решения о продвижении принимают по цифрам."},"world":{"text":"Во многих странах компании измеряют, какой канал рекламы приводит покупателей, и отказываются от тех, что не работают, чтобы не тратить ресурсы впустую. Это связано с ЦУР ООН № 12 «Ответственное потребление и производство»: лишние листовки — это ещё и лишняя бумага.","link":""},"fact":"Американскому предпринимателю Джону Ванамейкеру приписывают знаменитую фразу: «Половина денег, которые я трачу на рекламу, тратится впустую; беда в том, что я не знаю, какая половина». Именно поэтому маркетологи учатся считать отдачу от каждого канала (энциклопедия, статья «Джон Ванамейкер»).","cards":[{"n":"2","title":"Разбор каналов первой ярмарки","lines":["Заполните по своему листу учёта: Канал | Затраты | Покупатели | Выручка | Затраты на одного покупателя.","Пример для проверки (печенье по 200 условных тенге): плакат — 500, 5 покупателей; листовки — 500, 2 покупателя; зазывала — 0, 12 покупателей; дегустация — 0, 8 покупателей. Посчитайте выручку каждого канала и затраты на одного покупателя. (Ответ: плакат — 1 000 и 100; листовки — 400 и 250; зазывала — 2 400 и 0; дегустация — 1 600 и 0.) Решите: что оставить, усилить, убрать."],"hand":null,"answers":[]},{"n":"3","title":"Событие второго раунда","lines":["«Покупатели торопятся: перемена короткая». Какой канал сработает лучше в такой ситуации и почему? Проверьте на деле."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"Половина денег зря","minutes":9,"source":"Высказывание, которое приписывают Джону Ванамейкеру, владельцу универмагов в США, конец XIX века","hook":"«Половина денег на рекламу тратится впустую. Беда в том, что я не знаю, какая половина».","story":["Джон Ванамейкер — владелец одних из первых больших универмагов в США — много тратил на рекламу в газетах.","Ему приписывают знаменитые слова: «Половина денег на рекламу тратится впустую, но я не знаю, какая».","Тогда нельзя было точно узнать, какая реклама привела покупателя."],"question":"Как сегодня можно узнать, какой канал продвижения сработал?","options":["Угадать","Спросить покупателя или дать каждому каналу свой промокод","Посчитать лайки","Никак"],"answerIndex":1,"reveal":"Сегодня у каждого канала можно сделать свою метку: промокод, QR-код, ссылку или просто спросить «Откуда вы о нас узнали?». Тогда видно, какая «половина» работает.","teams":"Команды: по данным ярмарки определите, какой канал привёл больше покупателей. Что было бы, если бы спрашивали каждого?","takeaway":"Измеряй каждый канал, чтобы не тратить деньги зря."},{"type":"case","title":"Три канала — три кода","minutes":8,"source":"Условная ситуация","hook":"Команда продвигала ярмарку тремя способами. Какой сработал лучше?","story":["Команда продавала печенье. Сделали плакат в коридоре, пост в чате класса и выступление на линейке.","Каждому каналу дали свой «пароль» для скидки: «плакат», «чат», «линейка».","Пришли 40 покупателей: 6 сказали «плакат», 24 — «чат», 10 — «линейка». На плакат потратили 1 500 тенге, остальное бесплатно."],"question":"Какой канал сработал лучше всего?","options":["Чат класса: больше всего покупателей и бесплатно","Все одинаково","Плакат: он самый красивый","Линейка: она самая громкая"],"answerIndex":0,"reveal":"Чат привёл 24 из 40 покупателей (60%) бесплатно. Плакат стоил 1 500 тенге и привёл 6 покупателей — 250 тенге за одного. Цифры помогают решить, куда вкладывать силы в следующий раз.","teams":"Команды: посчитайте «стоимость одного покупателя» для каналов вашей ярмарки.","takeaway":"Лучший канал — тот, что даёт больше покупателей за меньшие деньги."}],"homework":"По отчёту команды напиши 3–4 предложения: какой канал сработал лучше всего, какие цифры это доказывают и что ты посоветуешь команде на следующей ярмарке.","support":"Таблица с формулой в шапке («затраты : покупатели») и примером одной заполненной строки.","advanced":"Посчитать прибыль с учётом затрат на продвижение по каждому каналу отдельно и построить столбчатую диаграмму покупателей по каналам.","photo":{"src":"lessons/img/06_28.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Как сделать продвижение эффективным и бережным к природе?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l28.pptx","name":"28. После ярмарки — какой канал продвижения сработал (6 кл).pptx","mb":1.2}},{"id":"06_29","g":6,"l":29,"topic":"Маркетинговый проект: этапы и защита: практикум","module":"Маркетинг","format":"Питч и защита","skills":["Лидерство","Работа с клиентом","Презентация"],"goal":"К концу урока команда сможет защитить маркетинговый проект в 3-минутном питче, показав результат продвижения цифрами из ярмарки (покупатели, выручка, прибыль, лучший канал), и ответить на 2 вопроса «инвесторов».","criteria":["Я показываю в питче результат продвижения конкретными цифрами из ярмарки.","Я объясняю, какой канал сработал и что команда изменила после ярмарки.","Я уверенно выступаю со своей частью и отвечаю на вопрос инвестора."],"result":"Финальный питч маркетингового проекта команды (3 минуты) со слайдом или плакатом «Результат продвижения в цифрах» и лист оценки питчей других команд.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Питчи","min":20},{"stage":"Голосование","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя и продать ему нужный товар","shown":"Работа, чтобы понять покупателя и продать ему нужный товар","truth":true,"first":"М"},{"term":"Проект (project)","real":"Дело с целью, сроком, командой и результатом","shown":"То, что изменилось благодаря продвижению: сколько покупателей пришло, сколько продали, какая прибыль","truth":false,"first":"П"},{"term":"Стартап","real":"Новый проект на первых этапах","shown":"Новый проект на первых этапах","truth":true,"first":"С"},{"term":"Услуга","real":"Работа, которую делают для покупателя","shown":"Дело с целью, сроком, командой и результатом","truth":false,"first":"У"},{"term":"Модель 5P","real":"План из 5 частей: товар, цена, место, продвижение, люди","shown":"План из 5 частей: товар, цена, место, продвижение, люди","truth":true,"first":"М"},{"term":"Результат продвижения","real":"То, что изменилось благодаря продвижению: сколько покупателей пришло, сколько продали, какая прибыль","shown":"Работа, которую делают для покупателя","truth":false,"first":"Р"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя и продать ему нужный товар"},{"term":"Проект (project)","def":"Дело с целью, сроком, командой и результатом"},{"term":"Стартап","def":"Новый проект на первых этапах"},{"term":"Услуга","def":"Работа, которую делают для покупателя"},{"term":"Модель 5P","def":"План из 5 частей: товар, цена, место, продвижение, люди"},{"term":"Результат продвижения","def":"То, что изменилось благодаря продвижению: сколько покупателей пришло, сколько продали, какая прибыль"},{"term":"Практика (practice)","def":"Выполнение задания на деле"}],"english":"marketing — маркетинг; project — проект; practice — практика","concepts":{"head":"Понятия","items":["Защита проекта (project) — это питч, где команда показывает не только идею, но и результат.","Результат продвижения — цифры: покупатели, выручка, прибыль, лучший канал.","Сегодня практика (practice): финальная защита маркетингового проекта."]},"steps":{"head":"Как построить финальный питч, по шагам","items":["Крючок — самая яркая цифра («Нас нашли 25 покупателей за 18 минут!»); товар и покупатель; план 5P в двух фразах; продвижение: какие каналы использовали; результат в цифрах: покупатели, выручка, прибыль, лучший канал и затраты на одного покупателя; выводы: что изменили бы; призыв к инвесторам","Подготовка: каждый берёт часть, репетиция с таймером, заранее готовим ответы на вопросы «Почему такая цена?», «Что не сработало?»"]},"scheme":"«часы питча» на 3 минуты с секторами: крючок — товар — 5P — продвижение — результат в цифрах — выводы — призыв; рядом 4 критерия оценки.","examples":[{"lab":"Пример","text":"Питч команды «Тёплая кружка»: «Мы продали 25 стаканов чая по 150 условных тенге — выручка 3 750. Затраты 1 500 на чай и 500 на плакат, прибыль 1 750. Лучший канал — дегустация: 11 покупателей бесплатно. Плакат привёл 5 покупателей, на одного — 100 условных тенге. В следующий раз мы уберём листовки и добавим вторую дегустацию»."},{"lab":"Казахстанский пример","text":"На демо-днях в Astana Hub стартапы показывают инвесторам не только идею, но и первые результаты: число клиентов и продаж."}],"mistake":{"myth":"Команда рассказывает только идею и забывает про результат ярмарки","fix":"На репетиции тренер задаёт вопрос «Покажите цифры» и просит перестроить питч."},"check":[{"q":"Почему результат лучше показывать цифрами?","a":"Цифрам верят, их можно проверить"},{"q":"Нужно ли рассказывать о том, что не сработало?","a":"Да, это показывает, что команда учится"},{"q":"Что такое затраты на одного покупателя?","a":"Затраты канала : число покупателей"}],"kz":{"text":"Astana Hub — международный технопарк IT-стартапов в Астане. На мероприятиях технопарка казахстанские стартапы выступают перед инвесторами и рассказывают о своих результатах: сколько клиентов, какие продажи.","link":"сегодня мы делаем такой же демо-день в классе."},"world":{"text":"По всему миру проводятся «демо-дни», где стартапы показывают инвесторам первые результаты. Инвесторы особенно ценят команды, которые честно говорят о своих ошибках и умеют учиться на цифрах.","link":""},"fact":"Известный инвестор Уоррен Баффетт в детстве продавал жевательную резинку, газировку и газеты и вёл учёт своих заработков; он часто говорит, что важно вкладывать в то, что понимаешь и что подтверждено цифрами (книги и интервью Уоррена Баффетта).","cards":[{"n":"1","title":"А теперь вопрос","lines":["По хлопку все меняются местами. Последний севший отвечает 20 секунд.","Вопросы: «Какая цифра нашей ярмарки тебя удивила?», «Какой навык помог тебе на ярмарке?»."],"hand":null,"answers":[]},{"n":"2","title":"Финальный питч (3 минуты)","lines":["1) Крючок — яркая цифра (15 сек). 2) Товар и покупатель (20 сек). 3) План 5P в двух фразах (25 сек). 4) Продвижение: каналы и бюджет (25 сек). 5) Результат в цифрах: покупатели, выручка, затраты, прибыль, лучший канал, затраты на одного покупателя (45 сек). 6) Что изменили бы (20 сек). 7) Призыв (10 сек).","Пример расчёта: 25 стаканов по 150 условных тенге, затраты на чай 1 500, на плакат 500."],"hand":null,"answers":[["","Выручка 3 750, прибыль 1 750."]]},{"n":"3","title":"Лист оценки «инвестора»","lines":["Команда ___. Критерии (1–10): результат в цифрах ___; понятность ___; честный вывод об ошибках ___; уверенная подача и ответы ___. Мой вопрос команде: ___. Сколько условных тенге из 10 000 вкладываю и почему: ___."],"hand":null,"answers":[]}],"practice":[{"type":"case","title":"Прыжок из стратосферы","minutes":9,"source":"Red Bull Stratos, Феликс Баумгартнер, 14 октября 2012","hook":"Компания-производитель напитков устроила прыжок с высоты около 39 км. Зачем?","story":["В 2012 году австриец Феликс Баумгартнер поднялся на воздушном шаре в стратосферу и прыгнул вниз.","Во время падения он преодолел скорость звука без самолёта.","Проект организовала компания Red Bull, а прямую трансляцию на YouTube смотрели миллионы людей одновременно."],"question":"Как этот проект связан с брендом Red Bull?","options":["Никак, это просто спорт","Бренд связывает себя с экстримом и смелостью — «Red Bull окрыляет»","Это был научный проект NASA","Феликс рекламировал парашюты"],"answerIndex":1,"reveal":"Red Bull продвигает не напиток, а образ смелости и приключений. Прыжок идеально подошёл к слогану «Red Bull окрыляет». Маркетинговый проект работает, когда событие совпадает с ценностями бренда.","teams":"Команды: придумайте событие для своего товара, которое совпадает с его ценностями. Как его защитить перед жюри?","takeaway":"Событие должно совпадать с ценностями бренда."},{"type":"case","title":"Защита за 90 секунд","minutes":8,"source":"Условная ситуация","hook":"Две команды защищают одинаковые проекты. Почему одна побеждает?","story":["Команда А 90 секунд читала с листа список: «наш товар — браслеты, цена 500 тенге, материалы — бусины…».","Команда Б начала с истории покупателя, показала цифры продаж с ярмарки и закончила одной просьбой к жюри.","У обеих команд одинаковый товар и одинаковая выручка."],"question":"Почему жюри выбрало команду Б?","options":["У них дороже товар","Они говорили громче","Понятная структура: история, факты и чёткий вывод","Жюри — их друзья"],"answerIndex":2,"reveal":"Защита — это тоже продвижение. Жюри запоминает историю, верит цифрам и любит чёткий вывод. Список фактов без структуры забывается сразу.","teams":"Команды: перестройте свою защиту по схеме «история — цифры — просьба» и прорепетируйте.","takeaway":"Защита проекта — это продвижение самой команды."}],"homework":"Напиши короткое письмо-благодарность «инвестору» (однокласснику), который вложил в ваш проект больше всего: что ваша команда сделает с его поддержкой и какой результат вы обещаете в следующий раз.","support":"Шаблон слайда «Результат в цифрах» с готовыми строками (покупатели, выручка, затраты, прибыль, лучший канал) и короткая часть питча с началом фразы.","advanced":"Подготовить ответ на вопрос «Как вы увеличите прибыль в 2 раза?» с расчётом и выступить «главным инвестором», задающим вопросы другим командам.","photo":{"src":"lessons/img/06_29.jpg","author":"Product School","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему инвестору важно услышать, что у команды не получилось?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l29.pptx","name":"29. Маркетинговый проект — этапы и защита — практикум (6 кл).pptx","mb":1.4}},{"id":"06_30","g":6,"l":30,"topic":"Итоговая работа за полугодие (Итоговое обобщение)","module":"Маркетинг","format":"Итоговая работа","skills":["Работа с клиентом","Критическое мышление","Финансовое мышление"],"goal":"К концу урока ученик сможет самостоятельно выполнить итоговую работу за полугодие по модулю «Маркетинг»: ответить на 10 тестовых вопросов по терминам и решить практическое задание — составить мини-план продвижения товара по модели 5P с расчётом бюджета и прибыли.","criteria":["Я правильно отвечаю не меньше чем на 7 из 10 вопросов теста.","Я составляю мини-план 5P, где каждый пункт конкретен, а бюджет не превышен.","Я правильно считаю выручку и прибыль и проверяю себя по чек-листу."],"result":"Выполненная итоговая работа: тест из 10 вопросов и практическое задание «Продвигаем товар» (5P, слоган, каналы с бюджетом, расчёт прибыли), а также рисунок «Моя дорога полугодия» для рефлексии.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Маркетинг (marketing)","real":"Работа, чтобы понять покупателя, сделать нужный товар и продать его","shown":"Работа, чтобы понять покупателя, сделать нужный товар и продать его","truth":true,"first":"М"},{"term":"Коммуникация (communication)","real":"Общение компании с покупателями: что, где и как ей говорить","shown":"Товар, цена, место, продвижение, люди","truth":false,"first":"К"},{"term":"Повторение (review)","real":"Возвращение к изученному, чтобы закрепить знания и найти пробелы","shown":"Возвращение к изученному, чтобы закрепить знания и найти пробелы","truth":true,"first":"П"},{"term":"Реклама","real":"Платное сообщение о товаре; PR — работа над доверием и репутацией","shown":"Общение компании с покупателями: что, где и как ей говорить","truth":false,"first":"Р"},{"term":"Бренд","real":"Образ товара или компании в голове покупателя","shown":"Образ товара или компании в голове покупателя","truth":true,"first":"Б"},{"term":"Модель 5P","real":"Товар, цена, место, продвижение, люди","shown":"Платное сообщение о товаре; PR — работа над доверием и репутацией","truth":false,"first":"М"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Маркетинг (marketing)","def":"Работа, чтобы понять покупателя, сделать нужный товар и продать его"},{"term":"Коммуникация (communication)","def":"Общение компании с покупателями: что, где и как ей говорить"},{"term":"Повторение (review)","def":"Возвращение к изученному, чтобы закрепить знания и найти пробелы"},{"term":"Реклама","def":"Платное сообщение о товаре; PR — работа над доверием и репутацией"},{"term":"Бренд","def":"Образ товара или компании в голове покупателя"},{"term":"Модель 5P","def":"Товар, цена, место, продвижение, люди"},{"term":"Канал продвижения","def":"Способ, которым покупатель узнаёт о товаре"}],"english":"communication — коммуникация; marketing — маркетинг; review — повторение","concepts":{"head":"Понятия полугодия","items":["маркетинг (marketing) и коммуникация (communication) с покупателем; реклама, её виды и 4 ступени влияния (внимание — интерес — желание — действие); требования к честной рекламе; PR и его отличие от рекламы; бренд и его элементы; личный бренд; рекламное агентство и 6 шагов кампании; план продвижения и модель 5P; каналы продвижения и затраты на одного покупателя."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитать все задания; тест — 12 минут; практическое задание — 16 минут; проверка по чек-листу","Трудный вопрос пропустить и вернуться позже"]},"scheme":"«дорога полугодия» — указатели: Реклама → Как работает реклама → PR → Бренд → Личный бренд → Агентства → Продвижение и 5P → Ярмарка; внизу таймер: тест 12 мин → практика 16 мин → самопроверка 4 мин.","examples":[{"lab":"Пример 1","text":"«Плакат стоил 600 условных тенге и привёл 4 покупателей. Затраты на одного?» — 150."},{"lab":"Пример 2 (казахстанский)","text":"«Air Astana: логотип с орнаментом, фирменные цвета, обещание надёжных полётов — это элементы чего?» — бренда."}],"mistake":{"myth":"В плане 5P пишут общие слова («хороший товар», «реклама везде»)","fix":"Напомнить, что баллы ставятся за конкретику — цифры, место, название канала."},"check":[{"q":"Чем PR отличается от рекламы?","a":"PR — доверие и репутация, о нём говорят другие; реклама — платное сообщение о продаже"},{"q":"Как посчитать прибыль?","a":"Выручка − все затраты"}],"kz":{"text":"Национальная команда Казахстана на международных олимпиадах школьников. Казахстанские школьники регулярно привозят медали с международных олимпиад, а перед этим проходят несколько этапов проверки знаний.","link":"каждая проверка показывает, что уже получается, а над чем работать."},"world":{"text":"ЦУР ООН № 4 «Качественное образование» говорит о том, что проверка знаний помогает понять, чему ещё учиться. Во многих странах школьники в конце полугодия выполняют итоговые работы и потом разбирают ошибки с учителем.","link":""},"fact":"Первые экзамены для отбора чиновников проводились в Древнем Китае более тысячи лет назад: кандидаты писали работы много часов, и от результата зависела их должность (энциклопедия, статья «Государственные экзамены в Китае»).","cards":[{"n":"1","title":"Итоговый тест (по 1 баллу)","lines":["1) Что из этого — признак рекламы? А) адресована многим людям Б) это личное письмо другу.","2) Расставьте ступени влияния рекламы: желание, внимание, действие, интерес.","3) Реклама должна быть: А) правдивой и конкретной Б) самой громкой.","4) Статья журналиста о благотворительной акции компании — это: А) реклама Б) PR.","5) Назовите 3 элемента бренда.","6) Обновление логотипа и слогана компании называется…","7) С чего начинается работа рекламного агентства? А) с размещения Б) с брифа.","8) Что обозначает Place в модели 5P?","9) Плакат стоил 600 условных тенге и привёл 4 покупателей. Затраты на одного покупателя?","10) Выручка 5 000, затраты на товар 1 500, на продвижение 1 000. Прибыль?"],"hand":null,"answers":[["1","А"],["2","Внимание — интерес — желание — действие."],["3","А"],["4","Б"],["5","Название, логотип, цвета, слоган, обещание — любые 3."],["6","Ребрендинг"],["7","Б"],["8","Место: где и как продаём."],["9","150."],["10","2 500."]]},{"n":"2","title":"Практическое задание «Продвигаем товар» (10 баллов)","lines":["Товар: браслеты ручной работы, затраты 200 условных тенге за штуку. Покупатели — ученики 5–8 классов. Бюджет на продвижение — до 1 500. Прайс-лист: плакат — 500, листовка — 25, школьное радио — 1 000, мини-выставка — бесплатно.","а) Заполните 5P: товар, цена, место, продвижение, люди (5 баллов). б) Придумайте честный слоган до 6 слов (1 балл). в) Выберите каналы и посчитайте бюджет (2 балла). г) Посчитайте выручку и прибыль, если продадите 20 браслетов по выбранной цене (2 балла)."],"hand":null,"answers":[]},{"n":"3","title":"Чек-лист самопроверки","lines":["Ответил(а) на все 10 вопросов.","В плане 5P у каждой буквы конкретный ответ.","Бюджет продвижения не больше 1 500.","Прибыль = выручка − затраты на товар − затраты на продвижение.","Слоган честный и без преувеличений."],"hand":null,"answers":[]}],"homework":"Повтори по тетради одну тему полугодия, которая была самой трудной, и запиши 2 вопроса к ней для работы над ошибками.","support":"Вариант теста с подсказкой-словарём из 7 терминов и шаблон таблицы 5P для практического задания.","advanced":"Дополнительное задание: добавить к плану PR-событие и посчитать, сколько товаров нужно продать, чтобы окупить бюджет продвижения.","photo":{"src":"lessons/img/06_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Как итоговая работа помогает вам спланировать следующее полугодие?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l30.pptx","name":"30. Итоговая работа за полугодие (Итоговое обобщение) (6 кл).pptx","mb":1.3}},{"id":"06_31","g":6,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Маркетинг","format":"Итоговая работа","skills":["Критическое мышление","Работа с клиентом","Финансовое мышление"],"goal":"К концу урока ученик сможет найти не меньше 2 своих ошибок в итоговой работе по маркетингу, определить их причину, исправить их и после обратной связи тренера верно выполнить похожее задание.","criteria":["Я нахожу свои ошибки и записываю правильный ответ.","Я называю причину каждой ошибки и правило, которое нужно помнить.","Я решаю похожее задание верно и использую обратную связь тренера, чтобы улучшить свой план 5P."],"result":"«Лист работы над ошибками»: таблица «Ошибка — правильный ответ — причина — похожее задание решено верно», исправленный план 5P и личная цель на следующее полугодие.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ошибка (mistake)","real":"Неверный ответ или действие; сигнал, что нужно доучить","shown":"Неверный ответ или действие; сигнал, что нужно доучить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Сообщение о том, что получилось и что улучшить","shown":"Ответ с фактами и цифрами, а не общими словами","truth":false,"first":"О"},{"term":"Причина ошибки","real":"То, из-за чего ошибка произошла: не знал термин, невнимательно прочитал, ошибся в расчёте, ответил слишком общо","shown":"То, из-за чего ошибка произошла: не знал термин, невнимательно прочитал, ошибся в расчёте, ответил слишком общо","truth":true,"first":"П"},{"term":"Работа над ошибками","real":"Исправление, поиск причины и тренировка на похожем задании","shown":"Сообщение о том, что получилось и что улучшить","truth":false,"first":"Р"}],"perm":[1,2,3,0]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный ответ или действие; сигнал, что нужно доучить"},{"term":"Обратная связь (feedback)","def":"Сообщение о том, что получилось и что улучшить"},{"term":"Причина ошибки","def":"То, из-за чего ошибка произошла: не знал термин, невнимательно прочитал, ошибся в расчёте, ответил слишком общо"},{"term":"Работа над ошибками","def":"Исправление, поиск причины и тренировка на похожем задании"},{"term":"Конкретность","def":"Ответ с фактами и цифрами, а не общими словами"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Понятия","items":["Ошибка (mistake) — нормальная часть обучения и бизнеса: компании тоже ошибаются в рекламе и исправляют её по цифрам.","Обратная связь (feedback) — подсказка, что получилось и что улучшить."]},"steps":{"head":"Как работать над ошибкой, по шагам","items":["Найти ошибку по отметке тренера; записать правильный ответ; определить причину (не знал термин; перепутал понятия, например рекламу и PR; ошибся в расчёте; ответил общими словами); повторить правило по тетради; решить похожее задание; попросить обратную связь тренера или партнёра"]},"scheme":"Цикл «Ошибка → Причина → Правило → Новая попытка → Обратная связь» и таблица «частые ошибки класса» без фамилий.","examples":[{"lab":"Пример","text":"Ошибка: «Прибыль = выручка − затраты на товар», а затраты на продвижение забыли. Причина — невнимательность к условию. Правило: прибыль = выручка − все затраты. Похожее задание: выручка 4 000, товар 1 200, продвижение 800 → прибыль 2 000. Ошибка-общие слова: в 5P «Продвижение: реклама везде». Исправление: «Плакат у столовой (500) и мини-выставка на большой перемене»."},{"lab":"Казахстанский пример","text":"Казахстанские компании после рекламной кампании смотрят, что не сработало, и меняют каналы или текст — это та же работа над ошибками."}],"mistake":{"myth":"Ученик переписывает ответ с доски, не разобравшись","fix":"Тренер просит устно объяснить одну исправленную ошибку и решить похожее задание без подсказки."},"check":[{"q":"Чем исправление отличается от работы над ошибкой?","a":"Работа над ошибкой включает причину и тренировку"},{"q":"Как сделать ответ в 5P конкретным?","a":"Добавить цифры, место, название канала"},{"q":"Зачем просить обратную связь?","a":"Чтобы увидеть то, что сам не замечаешь"}],"kz":{"text":"Казахстанские футбольные клубы, например «Астана» и «Кайрат». После каждого матча тренеры вместе с игроками разбирают видео игры и ошибки, чтобы следующий матч сыграть лучше.","link":"разбор ошибок и обратная связь — обычная часть работы профессионалов."},"world":{"text":"Во многих компаниях мира после неудачных проектов проводят разбор «что пошло не так» без поиска виноватых, чтобы не повторять ошибок. ЦУР ООН № 4 «Качественное образование» поддерживает обучение, в котором ошибка — часть пути.","link":""},"fact":"Компания Coca-Cola в 1985 году выпустила «новую колу» с изменённым вкусом, но покупатели были недовольны, и уже через несколько месяцев компания вернула классический вкус. Этот случай стал известным примером того, как бизнес признаёт ошибку и исправляет её по обратной связи покупателей (сайт компании Coca-Cola, энциклопедия, статья «New Coke»).","cards":[{"n":"1","title":"Лист работы над ошибками","lines":["Таблица: № задания | Моя ошибка | Правильный ответ | Причина (не знал термин / перепутал понятия / ошибся в расчёте / ответил общими словами) | Правило | Похожее задание решено верно?"],"hand":null,"answers":[]},{"n":"2","title":"Похожие задания","lines":["1) Выручка 4 000 условных тенге, затраты на товар 1 200, на продвижение 800. Прибыль?","2) Листовки стоили 750 и привели 3 покупателей. Затраты на одного?","3) Реклама или PR: «Школьная газета написала, что команда стартапа провела мастер-класс для младших». (PR.)","4) Расставьте шаги агентства: макет, бриф, оценка, идея, размещение, исследование. (Бриф — исследование — идея — макет — размещение — оценка.)","5) Перепишите конкретно: «Продвижение: реклама везде». (Пример: «Плакат у столовой за 500 и мини-выставка на большой перемене».)"],"hand":null,"answers":[["1","2 000."],["2","250."]]},{"n":"3","title":"Чек-лист самопроверки","lines":["Все ошибки исправлены.","У каждой указаны причина и правило.","Похожие задания решены.","План 5P стал конкретнее.","Записана личная цель со сроком."],"hand":null,"answers":[]}],"homework":"Реши ещё 2 похожих задания на тему, где была ошибка (выдаёт тренер), и запиши личную цель по маркетингу на следующее полугодие: что хочешь научиться делать и к какому сроку.","support":"Памятка с правилами (прибыль = выручка − все затраты; затраты на одного покупателя = затраты канала : покупатели; отличия рекламы и PR; 5P) и список возможных причин ошибок.","advanced":"Составить 2 похожих задания по своей сильной теме с ответами для одноклассников и помочь в паре тому, кому трудно.","photo":{"src":"lessons/img/06_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Какая ошибка в этом полугодии научила вас большему всего?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (6 кл).pptx","mb":1.3}},{"id":"06_32","g":6,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Маркетинг","format":"Деловая игра","skills":["Лидерство","Работа с клиентом","Командная работа"],"goal":"К концу урока ученик сможет в командной игре «Маркетинговое агентство» применить понятия полугодия (виды рекламы, 4 ступени влияния, PR, бренд, бриф, 5P, каналы продвижения) для решения заданий клиента и верно ответить на вопросы по темам, где в итоговой работе были ошибки.","criteria":["Я применяю понятия полугодия, чтобы решить задание клиента.","Я выполняю свою роль в агентстве и помогаю команде.","Я объясняю на разборе, почему решение команды сработало."],"result":"Игровой «Портфель агентства»: решения команды по заданиям двух раундов, мини-кампания для клиента с бюджетом в условных тенге и итоговый счёт баллов.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Повторение (review)","real":"Возвращение к изученному, чтобы закрепить знания","shown":"Возвращение к изученному, чтобы закрепить знания","truth":true,"first":"П"},{"term":"Игра (game)","real":"Занятие по правилам, где команды решают задачи и получают баллы","shown":"Этап работы, где всё задерживается и тормозит всю команду","truth":false,"first":"И"},{"term":"Бриф","real":"Задание клиента: что рекламируем, для кого, зачем, бюджет и срок","shown":"Задание клиента: что рекламируем, для кого, зачем, бюджет и срок","truth":true,"first":"Б"},{"term":"Модель 5P","real":"Товар, цена, место, продвижение, люди","shown":"Занятие по правилам, где команды решают задачи и получают баллы","truth":false,"first":"М"},{"term":"Канал продвижения","real":"Способ, которым покупатель узнаёт о товаре","shown":"Способ, которым покупатель узнаёт о товаре","truth":true,"first":"К"},{"term":"Узкое место","real":"Этап работы, где всё задерживается и тормозит всю команду","shown":"Товар, цена, место, продвижение, люди","truth":false,"first":"У"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Повторение (review)","def":"Возвращение к изученному, чтобы закрепить знания"},{"term":"Игра (game)","def":"Занятие по правилам, где команды решают задачи и получают баллы"},{"term":"Бриф","def":"Задание клиента: что рекламируем, для кого, зачем, бюджет и срок"},{"term":"Модель 5P","def":"Товар, цена, место, продвижение, люди"},{"term":"Канал продвижения","def":"Способ, которым покупатель узнаёт о товаре"},{"term":"Узкое место","def":"Этап работы, где всё задерживается и тормозит всю команду"}],"english":"review — повторение; game — игра","concepts":{"head":"Понятия, которые проверяем","items":["реклама и её виды; 4 ступени влияния (внимание — интерес — желание — действие); честная реклама; PR и его отличие от рекламы; бренд и ребрендинг; личный бренд; рекламное агентство, бриф и 6 шагов кампании; план продвижения и 5P; затраты на одного покупателя; выручка и прибыль.","Повторение (review) в форме игры (game)."]},"steps":{"head":"Как проходит игра, по шагам","items":["Команды по 4–5 человек становятся агентствами и распределяют роли (агент, копирайтер, дизайнер, медиапланер, счётчик); раунд 1 — «Экзамен агентства»: 6 быстрых заданий по 1,5 минуты, за верный ответ 2 балла; раунд 2 — «Заказ клиента»: бриф, бюджет и событие рынка, команда готовит мини-кампанию; на разборе команды объясняют решения"]},"scheme":"«карта агентства» — 6 кабинетов-станций (Реклама, Влияние, PR, Бренд, Бриф, 5P) и выход «Клиент доволен»; рядом таблица баллов.","examples":[{"lab":"Пример","text":"«Плакат стоил 900 условных тенге и привёл 6 покупателей — затраты на одного?» (150.) Казахстанский"},{"lab":"Пример для станции «Бренд»","text":"«Логотип с орнаментом, фирменные цвета, обещание надёжных полётов — бренд какой казахстанской компании?» (Air Astana.)"}],"mistake":{"myth":"Команда предлагает кампанию без расчёта бюджета или с обещаниями, которые нельзя проверить","fix":"Баллы за раунд 2 даются только при расчёте и честном слогане."},"check":[{"q":"Какая роль в агентстве стала узким местом?","a":"Ответы команд, например медиапланер долго считал бюджет"},{"q":"Почему клиенту важны цифры в кампании?","a":"Он видит, на что пойдут деньги и как проверить результат"},{"q":"Чем PR помог бы клиенту?","a":"Повысил бы доверие"}],"kz":{"text":"Astana Hub — международный технопарк IT-стартапов в Астане. Стартапы там учатся продвигать свои продукты, работать с клиентами и защищать проекты.","link":"всё, что мы изучили за полугодие — реклама, PR, бренд, 5P, — нужно любой молодой компании."},"world":{"text":"ЦУР ООН № 17 «Партнёрство ради целей»: рекламные агентства разных стран часто объединяются для больших социальных кампаний, например о чистой воде или защите природы.","link":""},"fact":"Модель маркетинга «4P» (товар, цена, место, продвижение) предложил американский профессор Джером Маккарти в 1960 году; позже к ней стали добавлять пятое P — людей, потому что покупателю важен сервис (энциклопедия, статья «Комплекс маркетинга»).","cards":[{"n":"2","title":"Раунд 1: экзамен агентства (по 2 балла)","lines":["1) Вид рекламы: щит на остановке. (Наружная.)","2) Какая ступень влияния: «Только до пятницы — вторая штука за полцены!»?","3) Реклама или PR: новость о субботнике, который провела компания. (PR.)","4) Бренд: логотип с орнаментом, фирменные цвета, обещание надёжных полётов. (Air Astana.)","5) С чего начинается работа агентства?","6) Плакат стоил 900 условных тенге и привёл 6 покупателей. Затраты на одного?"],"hand":null,"answers":[["2","Действие."],["5","С брифа."],["6","150."]]},{"n":"3","title":"Раунд 2: заказ клиента","lines":["Бриф: школьная мастерская продаёт новогодние открытки по 300 условных тенге; затраты 100 за штуку; покупатели — ученики и учителя; цель — 40 открыток; бюджет продвижения — 2 000. Прайс-лист: плакат — 500, листовка — 25, школьное радио — 1 000, выставка — бесплатно.","Задание: идея и честный слоган; 2–3 канала в рамках бюджета; расчёт выручки и прибыли при продаже 40 открыток.","Событие: «У соседнего агентства заболел дизайнер». Поможете? Бонус 3 балла за взаимопомощь."],"hand":"Сдать: портфель с решениями.","answers":[["","Выручка 12 000; прибыль 12 000 − 4 000 − затраты на продвижение, например при 2 000 — 6 000."]]}],"practice":[{"type":"case","title":"Угадай бренд: книга о ките","minutes":6,"source":"История названия Starbucks","hook":"Название сети кофеен взяли из романа о ките. Какая это сеть?","story":["Основатели сети кофеен из Сиэтла (1971) искали название, связанное с морем и торговыми путями.","Они выбрали имя помощника капитана из романа «Моби Дик» Германа Мелвилла.","На логотипе — морская сирена."],"question":"Какая это сеть?","options":["Nescafé","Dunkin'","Starbucks","Costa"],"answerIndex":2,"reveal":"Это Starbucks: имя первого помощника капитана в «Моби Дике» — Старбак. Название связывает кофе с морскими путешествиями.","teams":"Команды: придумайте название бренда, у которого есть своя история.","takeaway":"У сильного названия есть история."},{"type":"case","title":"PR или реклама?","minutes":6,"source":"Повторение: реклама и PR","hook":"Компания заплатила за ролик на ТВ, а другая — посадила деревья в парке и о ней написали новости. Где PR?","story":["Компания А купила рекламу на ТВ: «Наш сок самый вкусный».","Компания Б устроила субботник в парке, о нём написали городские новости.","Компания В рассказала в соцсетях, как исправила ошибку с доставкой."],"question":"Какие примеры относятся к PR?","options":["Б и В — они строят репутацию и отношения","Все три — реклама","Ни один","Только А"],"answerIndex":0,"reveal":"Реклама — платное сообщение о товаре. PR строит репутацию и доверие: события, новости, честная реакция на ошибки.","teams":"Команды: придумайте одну PR-акцию для бренда вашего ярмарочного товара.","takeaway":"Реклама продаёт товар, PR — доверие к бренду."}],"homework":"Придумай один вопрос-задание по любой теме полугодия по маркетингу для следующей игры и запиши правильный ответ.","support":"Памятка с ключевыми понятиями и формулами (прибыль = выручка − все затраты; затраты на одного покупателя = затраты : покупатели; 5P) на каждую команду.","advanced":"Роль «эксперта клиента»: проверить мини-кампанию другого агентства и задать 2 вопроса; придумать дополнительное событие рынка.","photo":{"src":"lessons/img/06_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую социальную кампанию могли бы сделать вместе несколько агентств для вашего города?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g06-l32.pptx","name":"32. Игра-повторение по темам полугодия (6 кл).pptx","mb":1.5}}];
